90	/* ---------- animation exec callbacks (LVGL v9: (obj, value)) ---------- */
91	
92	/* LVGL v9 exec_cb signature is lv_anim_exec_xcb_t = void(*)(void*, lv_anim_value_t),
93	 * i.e. the first arg is the animated var (void*), NOT lv_obj_t* nor lv_anim_t*.
94	 * We cast to lv_obj_t* inside for the lv_obj and lv_arc calls. */
95	/* Spinner: a 90° segment rotating (THINKING / LISTENING). value = start angle. */
96	static void spin_cb(void *obj, int32_t v)
97	{
98	  lv_obj_t *o = (lv_obj_t *)obj;
99	  lv_arc_set_angles(o, v, v + 90);
100	}
101	
102	/* Growing fill: indicator grows 0→360 (EXECUTING). value = end angle. */
103	static void fill_cb(void *obj, int32_t v)
104	{
105	  lv_obj_t *o = (lv_obj_t *)obj;
106	  lv_arc_set_angles(o, 0, v);
107	}
108	
109	/* Breathing: face opacity pulses (IDLE). value 0..100. */
110	static void breathe_cb(void *obj, int32_t v)
111	{
112	  lv_obj_t *o = (lv_obj_t *)obj;
113	  /* 100% → 255, 0% → 190 (gentle). */
114	  lv_obj_set_style_opa(o, LV_OPA_COVER - (v * (LV_OPA_COVER - 190)) / 100, 0);
115	}
116	
117	/* Blink: both eyes opacity (WAITING). value 0..100, triangle-ish via sin-free. */
118	static void blink_cb(void *obj, int32_t v)
119	{
120	  lv_obj_t *o = (lv_obj_t *)obj;
121	  /* open(0) → closed(50) → open(100): opaque at ends, transparent at mid. */
122	  lv_opa_t op = (v < 50) ? LV_OPA_COVER - (v * 2)
123	                       : LV_OPA_TRANSP + ((v - 50) * 2 * LV_OPA_COVER / 100);
124	  if (op > LV_OPA_COVER) op = LV_OPA_COVER;
125	  lv_obj_set_style_opa(o, op, 0);
126	}
127	
128	/* Shake: face x jitter (ERROR). value 0..100 maps to a few oscillations. */
129	static void shake_cb(void *obj, int32_t v)
130	{
131	  lv_obj_t *o = (lv_obj_t *)obj;
132	  /* 0..100 → four half-swings of ±5px. Simple triangle per 25-step. */
133	  int seg = v / 25;
134	  int phase = v % 25;
135	  int amp = (phase < 13) ? (phase * 5 / 12) : ((25 - phase) * 5 / 12);
136	  int sign = (seg % 2 == 0) ? 1 : -1;
137	  lv_obj_set_style_translate_x(o, sign * amp, 0);
138	}
