278	/* ---------- screen show / hide ---------- */
279	
280	static void show_async_cb(void *data)
281	{
282	  (void)data;
283	  if (!s_pet.initialized || !s_pet.screen || s_pet.visible) return;
284	  s_pet.prev_screen = lv_screen_active();
285	  lv_screen_load(s_pet.screen);
286	  s_pet.visible = true;
287	  /* Re-assert current state's animation (lv_anim may have been paused off-screen). */
288	  start_anim_for(s_pet.state);
289	  syslog(LOG_INFO, "[%s] pet screen shown\n", TAG);
290	}
291	
292	void pet_status_view_show(void)
293	{
294	  if (!s_pet.initialized) return;
295	  lv_async_call(show_async_cb, NULL);
296	}
297	
298	static void hide_async_cb(void *data)
299	{
300	  (void)data;
301	  if (!s_pet.initialized || !s_pet.visible) return;
302	  stop_anim();
303	  if (s_pet.prev_screen) lv_screen_load(s_pet.prev_screen);
304	  s_pet.visible = false;
305	  syslog(LOG_INFO, "[%s] pet screen hidden\n", TAG);
306	}
307	
308	void pet_status_view_hide(void)
309	{
310	  if (!s_pet.initialized) return;
311	  lv_async_call(hide_async_cb, NULL);
312	}
