      s_pf.p[i].x = s_pf.cx + (int32_t)(((int64_t)rx * rr) / 0x7fff);
      s_pf.p[i].y = s_pf.cy + (int32_t)(((int64_t)ry * rr) / 0x7fff);
      s_pf.p[i].vx = lcg_next(&seed) / 8;   /* small initial velocity */
      s_pf.p[i].vy = lcg_next(&seed) / 8;
