755	                          fb_coord_t row_start, fb_coord_t row_end,
756	                          fb_coord_t col_start, fb_coord_t col_end,
757	                          FAR const uint8_t *buffer, fb_coord_t stride)
758	{
759	  FAR struct jd9853_dev_s *priv = (FAR struct jd9853_dev_s *)dev;
760	  size_t cols = col_end - col_start + 1;
761	  size_t rows = row_end - row_start + 1;
762	  size_t row_size = cols * (priv->bpp >> 3);
763	
764	  ginfo("row_start: %d row_end: %d col_start: %d col_end: %d\n",
765	         row_start, row_end, col_start, col_end);
766	
767	  DEBUGASSERT(buffer && ((uintptr_t)buffer & 1) == 0);
768	
769	  jd9853_setcursor(priv, col_start, row_start, col_end, row_end);
770	
771	  /* If the stride is the same of the row, a single SPI transfer is enough.
772	   * That is always true for lcddev. For framebuffer, that indicates a full
773	   * screen or full row update.
774	   */
775	
776	  if (stride == row_size)
777	    {
778	      /* simpler case, we can just send the whole buffer */
779	
780	      ginfo("Using full screen/full row mode\n");
781	      jd9853_wrram(priv, buffer, rows * row_size, 0, 1);
782	    }
783	  else
784	    {
785	      /* We have to go row by row */
786	
787	      ginfo("Falling-back to row by row mode\n");
788	      jd9853_wrram(priv, buffer, row_size, stride - row_size, rows);
789	    }
790	
791	  return OK;
792	}
