233	int bk7258_gpio_config_output(unsigned int pin, bool initial)
234	{
235	  irqstate_t flags;
236	  uint32_t regval;
237	
238	  if (!bk7258_gpio_valid(pin))
239	    {
240	      return -EINVAL;
241	    }
242	
243	  flags = enter_critical_section();
244	  bk7258_gpio_select_func_locked(pin);
245	
246	  /* Program the output latch while the output driver is still disabled, then
247	   * switch the pin to output mode.  Keeping both writes in one critical
248	   * section prevents another register update from introducing a glitch.
