 ****************************************************************************/

static void jd9853_sleep(FAR struct jd9853_dev_s *dev, bool sleep)
{
  if (sleep)
    {
      jd9853_sendcmd(dev, JD9853_SLEEP_IN);
    }
  else
    {
      jd9853_sendcmd(dev, JD9853_SLEEP_OUT);
    }

  up_mdelay(120);
}

