292	static void bk7258_spi_transfer(FAR struct bk7258_spi_dev_s *priv,
293	                                FAR const uint8_t *txbuf, FAR uint8_t *rxbuf,
294	                                size_t nwords)
295	{
296	  FAR bk7258_spi_hw_t *hw = priv->hw;
297	  uint32_t timeout;
298	
299	  while (nwords > 0)
300	    {
301	      size_t chunk = nwords > BK7258_SPI_MAX_TRANSFER ?
302	                     BK7258_SPI_MAX_TRANSFER : nwords;
303	      size_t i;
304	
305	      /* Start a master transmit of exactly `chunk` bytes.  Software CS is
306	       * already held low by jd9853/gc9d01 select() across a burst, so the
307	       * panel sees one continuous CS-low window even when the 4095-byte
308	       * hardware transfer cap forces chunking.
309	       */
310	
311	      hw->int_status.tx_fifo_clr = 1;   /* write-1-clear FIFO */
312	      hw->cfg.tx_trans_len = chunk;
313	      hw->cfg.tx_en = 1;
314	
315	      for (i = 0; i < chunk; i++)
316	        {
317	          timeout = BK7258_SPI_WR_READY_MAX;
318	          while (!hw->int_status.tx_fifo_wr_ready)
319	            {
320	              if (--timeout == 0)
321	                {
322	                  printf("SPI1: ERROR tx fifo not ready (status=%08x)\n",
323	                         (unsigned int)hw->int_status.v);
324	                  goto next_chunk;
325	                }
326	            }
327	
328	          hw->data.fifo_data = txbuf != NULL ? txbuf[i] : 0xff;
329	        }
330	
331	      /* Wait for the last byte to shift out before the next chunk. */
332	
333	      timeout = BK7258_SPI_FINISH_MAX;
334	      while (!hw->int_status.tx_finish_int)
335	        {
336	          if (--timeout == 0)
337	            {
338	              printf("SPI1: ERROR tx finish timeout "
339	                     "(status=%08x cfg=%08x dev_status=%08x)\n",
340	                     (unsigned int)hw->int_status.v,
341	                     (unsigned int)hw->cfg.v,
342	                     (unsigned int)hw->dev_status);
343	              break;
344	            }
345	        }
346	
347	next_chunk:
348	      hw->int_status.tx_finish_int = 1;  /* write-1-clear */
349	      hw->int_status.tx_fifo_int   = 1;  /* write-1-clear */
350	      hw->cfg.tx_en = 0;
351	
352	      if (txbuf != NULL)
353	        {
354	          txbuf += chunk;
355	        }
356	
357	      if (rxbuf != NULL)
358	        {
359	          memset(rxbuf, 0, chunk);
360	          rxbuf += chunk;
361	        }
362	
363	      nwords -= chunk;
364	    }
365	}
