210	/* ── Ring buffer ──────────────────────────────────────────────── */
211	
212	/**
213	 * Copy text into a fixed buffer with UTF-8-aware truncation.  Copies at most
214	 * dst_size-1 bytes, then if the cut lands inside a multi-byte UTF-8 sequence
215	 * (leading byte 0xC0..0xF4 not followed by enough continuation bytes 0x80..0xBF),
216	 * trims back to the last complete character.  Always NUL-terminates.
217	 *
218	 * This prevents a half-cut Chinese char from rendering as a replacement glyph
219	 * at the end of a truncated Agent reply.
220	 */
221	static void chat_view_copy_text(char* dst, const char* src, size_t dst_size)
222	{
223	    if (dst_size == 0) return;
224	    size_t n = strnlen(src, dst_size - 1);
225	    memcpy(dst, src, n);
226	    dst[n] = '\0';
227	
228	    /* If we filled the buffer, the last char may be incomplete.  Walk back
229	     * from the end to find a UTF-8 leading byte and check its expected length
230	     * against the remaining bytes. */
231	    if (n < dst_size - 1) return;          /* src fit fully, no truncation */
232	    size_t i = n;
233	    while (i > 0) {
234	        unsigned char c = (unsigned char)dst[i - 1];
235	        if ((c & 0xC0) != 0x80) break;     /* not a continuation byte */
236	        i--;
237	    }
238	    if (i == 0) return;                     /* all continuation bytes? give up */
239	    unsigned char lead = (unsigned char)dst[i - 1];
240	    size_t need;
241	    if      ((lead & 0x80) == 0x00) need = 1;   /* ASCII */
242	    else if ((lead & 0xE0) == 0xC0) need = 2;
243	    else if ((lead & 0xF0) == 0xE0) need = 3;
244	    else if ((lead & 0xF8) == 0xF0) need = 4;
245	    else { dst[i - 1] = '\0'; return; }         /* invalid lead, cut it */
246	    if (n - (i - 1) < need) {
247	        dst[i - 1] = '\0';                      /* incomplete seq, trim it */
248	    }
249	}
250	
251	/**
252	 * Add a message to the chat history ring buffer.
253	 *
254	 * When count < CHAT_HISTORY_MAX, writes at head and increments count.
255	 * When count == CHAT_HISTORY_MAX, overwrites the oldest message and
256	 * deletes its LVGL bubble widget if present.
257	 *
258	 * Text is truncated to LVGL_UI_MSG_MAX_LEN - 1 bytes with explicit
259	 * NUL termination (rule coding-9), UTF-8-aware so a multi-byte char is
260	 * never split in half.
261	 *
262	 * Returns pointer to the newly written slot (inside the ring buffer,
263	 * no stack allocation of chat_msg_t — rule coding-6).
264	 */
265	static chat_msg_t* chat_history_add(chat_history_t* h, const char* text, bool is_user)
266	{
267	    chat_msg_t* slot = &h->msgs[h->head];
268	
269	    /* When buffer is full, recycle the oldest slot */
270	    if (h->count == CHAT_HISTORY_MAX) {
271	        if (slot->bubble) {
272	            lv_obj_del(slot->bubble);
273	            slot->bubble = NULL;
274	        }
275	    } else {
276	        h->count++;
277	    }
278	
279	    /* Write message text with UTF-8-aware truncation */
280	    chat_view_copy_text(slot->text, text, LVGL_UI_MSG_MAX_LEN);
281	
282	    slot->is_user = is_user;
283	    slot->bubble = NULL;
284	
285	    h->head = (h->head + 1) % CHAT_HISTORY_MAX;
286	
287	    return slot;
288	}
