372	int lvgl_ui_channel_init(void)
373	{
374	    int chat_h;
375	    int ret = 0;
376	    /* Display geometry — queried from the active display so the layout
377	     * adapts to both the 466×466 round watch (real hardware) and the
378	     * 1280×800 rectangle (qemu). Falls back to the 466 constants when
379	     * no display is registered yet. */
380	    lv_coord_t disp_w = LVGL_UI_SCREEN_W;
381	    lv_coord_t disp_h = LVGL_UI_SCREEN_H;
382	
383	    /* Idempotent: already initialized */
384	    if (s_state.initialized) {
385	        return 0;
386	    }
387	
388	    syslog(LOG_INFO, "[%s] init\n", TAG);
389	
390	    /* If LVGL is not yet initialized (qemu: no miwear/launcher owns it),
391	     * bring it up ourselves: lv_init + lv_nuttx_init(/dev/fb0) + a
392	     * lv_timer_handler loop thread.  On real hardware where miwear already
393	     * did this, lv_is_initialized() is true and we skip — only creating
394	     * widgets on the existing display, as before. */
395	    if (!lv_is_initialized()) {
396	        lv_nuttx_dsc_t dsc;
397	
398	        syslog(LOG_INFO, "[%s] LVGL not initialized; self-init on /dev/fb0\n", TAG);
399	
400	        lv_init();
401	        lv_nuttx_dsc_init(&dsc);
402	        /* fb_path defaults to /dev/fb0 in lv_nuttx_dsc_init; GOLDFISH_GPU_FB
403	         * provides it on qemu-arm64-v8a-ap. */
404	        lv_nuttx_init(&dsc, &s_lv_result);
405	
406	        if (s_lv_result.disp == NULL) {
407	            syslog(LOG_ERR, "[%s] lv_nuttx_init failed (no display)\n", TAG);
408	            ret = -EIO;
409	            goto cleanup;
410	        }
411	
412	        /* Start the LVGL event loop thread (miwear would own this on real
413	         * hardware; on qemu we run it ourselves). */
414	        s_lv_loop_running = true;
415	        /* LVGL rendering + CJK (SIMSUN/FreeType) glyph rasterization needs a
416	         * deep stack; the default pthread stack overflows -> recursive
417	         * assert. Use an explicitly sized stack. */
418	        pthread_attr_t lv_attr;
419	        pthread_attr_init(&lv_attr);
420	        pthread_attr_setstacksize(&lv_attr, AGENT_LVGL_UI_STACK);
421	        if (pthread_create(&s_lv_loop_tid, &lv_attr, lv_loop_thread, NULL) != 0) {
422	            syslog(LOG_ERR, "[%s] LVGL loop thread create failed\n", TAG);
423	            lv_nuttx_deinit(&s_lv_result);
424	            s_lv_loop_running = false;
425	            ret = -EIO;
426	            goto cleanup;
427	        }
428	        s_lv_owned = true;
429	        syslog(LOG_INFO, "[%s] LVGL self-init OK, loop thread started\n", TAG);
430	    } else {
431	        syslog(LOG_INFO, "[%s] LVGL already initialized (system owns it)\n", TAG);
432	    }
433	
434	    /* Query the real display resolution so the layout adapts to the
435	     * actual screen (466 round watch on hardware, 1280×800 on qemu)
436	     * instead of always using the 466 constants. */
437	    lv_display_t* disp = lv_display_get_default();
438	    if (disp) {
439	        lv_coord_t rw = lv_display_get_horizontal_resolution(disp);
440	        lv_coord_t rh = lv_display_get_vertical_resolution(disp);
441	        if (rw > 0 && rh > 0) {
442	            disp_w = rw;
443	            disp_h = rh;
444	            syslog(LOG_INFO, "[%s] display %dx%d\n", TAG, disp_w, disp_h);
445	        }
446	    }
447	
448	    /* Create main screen with dark background */
449	    s_state.screen = lv_obj_create(NULL);
450	    if (!s_state.screen) {
451	        syslog(LOG_ERR, "[%s] screen create failed\n", TAG);
452	        ret = -EIO;
453	        goto cleanup;
454	    }
455	
456	    lv_obj_set_style_bg_color(s_state.screen, lv_color_hex(0x1a1a2e), 0);
457	    lv_obj_set_style_bg_opa(s_state.screen, LV_OPA_COVER, 0);
458	    /* Do NOT call lv_screen_load() here — we load the screen on
459	     * demand when the user activates the chat UI, to avoid
460	     * hijacking the system's current screen at boot. */
461	
462	    /* Default text font: the app-owned statically-compiled MiSans-16 CJK font
463	     * (3755 GB2312-1 common chars + ASCII + fullwidth punctuation, baked into
464	     * the binary via lv_font_conv — zero runtime malloc/rasterization) so
465	     * Agent reply Chinese text renders on qemu with full coverage and cannot
466	     * corrupt the heap.  Falls back to SimSun-16 (1000 chars) then Montserrat. */
467	    lv_obj_set_style_text_font(s_state.screen, &lv_font_misans_16_cjk, 0);
468	
469	    /* Step 5: Create Chat View container */
470	    chat_h = disp_h - LVGL_UI_PADDING_TOP - LVGL_UI_PADDING_BOTTOM
471	        - LVGL_UI_PTT_SIZE - 20;
472	
473	    s_state.chat_list = lv_obj_create(s_state.screen);
474	    if (!s_state.chat_list) {
475	        syslog(LOG_ERR, "[%s] chat_list create failed\n", TAG);
476	        ret = -EIO;
477	        goto cleanup;
478	    }
479	
480	    lv_obj_set_size(s_state.chat_list,
481	        disp_w - 2 * LVGL_UI_PADDING_H, chat_h);
482	    lv_obj_align(s_state.chat_list, LV_ALIGN_TOP_MID, 0, LVGL_UI_PADDING_TOP);
483	    lv_obj_set_scroll_dir(s_state.chat_list, LV_DIR_VER);
484	    lv_obj_set_flex_flow(s_state.chat_list, LV_FLEX_FLOW_COLUMN);
485	    lv_obj_set_style_pad_row(s_state.chat_list, LVGL_UI_CHAT_GAP, 0);
486	    lv_obj_set_style_bg_opa(s_state.chat_list, LV_OPA_TRANSP, 0);
487	    lv_obj_set_style_border_width(s_state.chat_list, 0, 0);
488	    lv_obj_set_style_pad_left(s_state.chat_list, 4, 0);
489	    lv_obj_set_style_pad_right(s_state.chat_list, 4, 0);
490	    lv_obj_set_style_pad_top(s_state.chat_list, 4, 0);
491	    lv_obj_set_style_pad_bottom(s_state.chat_list, 4, 0);
492	    lv_obj_set_scrollbar_mode(s_state.chat_list, LV_SCROLLBAR_MODE_OFF);
493	    lv_obj_add_flag(s_state.chat_list, LV_OBJ_FLAG_SCROLL_MOMENTUM);
494	
495	    /* Step 6: Create PTT Button */
496	    s_state.ptt_btn = lv_btn_create(s_state.screen);
497	    if (!s_state.ptt_btn) {
498	        syslog(LOG_ERR, "[%s] ptt_btn create failed\n", TAG);
499	        ret = -EIO;
500	        goto cleanup;
501	    }
502	
503	    lv_obj_set_size(s_state.ptt_btn, LVGL_UI_PTT_SIZE, LVGL_UI_PTT_SIZE);
504	    lv_obj_align(s_state.ptt_btn, LV_ALIGN_BOTTOM_MID, 0, -LVGL_UI_PADDING_BOTTOM);
505	    lv_obj_set_style_radius(s_state.ptt_btn, LVGL_UI_PTT_SIZE / 2, 0);
506	    lv_obj_set_style_bg_color(s_state.ptt_btn, lv_color_hex(0x4a90d9), 0);
507	    lv_obj_set_style_shadow_width(s_state.ptt_btn, 12, 0);
508	    lv_obj_set_style_shadow_color(s_state.ptt_btn, lv_color_hex(0x4a90d9), 0);
509	    lv_obj_set_style_shadow_opa(s_state.ptt_btn, LV_OPA_40, 0);
510	
511	    s_state.ptt_label = lv_label_create(s_state.ptt_btn);
512	    if (!s_state.ptt_label) {
513	        syslog(LOG_ERR, "[%s] ptt_label create failed\n", TAG);
514	        ret = -EIO;
515	        goto cleanup;
516	    }
517	
518	    /* Use Unicode microphone emoji — MiSans includes it, unlike
519	     * LV_SYMBOL_AUDIO which needs FontAwesome glyphs not in MiSans
520	     * and renders as a rectangle. */
521	    lv_label_set_text(s_state.ptt_label, PTT_ICON_MIC);
522	    lv_obj_center(s_state.ptt_label);
523	
524	    lv_obj_add_event_cb(s_state.ptt_btn, ptt_btn_event_cb, LV_EVENT_ALL, NULL);
525	
526	    /* Step 7: Create Recording Indicator (initially hidden) */
527	    s_state.rec_indicator = lv_label_create(s_state.screen);
528	    if (!s_state.rec_indicator) {
529	        syslog(LOG_ERR, "[%s] rec_indicator create failed\n", TAG);
530	        ret = -EIO;
531	        goto cleanup;
532	    }
533	
534	    lv_label_set_text(s_state.rec_indicator, "");
535	    lv_obj_align_to(s_state.rec_indicator, s_state.ptt_btn, LV_ALIGN_OUT_TOP_MID, 0, -8);
536	    lv_obj_add_flag(s_state.rec_indicator, LV_OBJ_FLAG_HIDDEN);
537	
538	    /* Step 7b: Create Close Button (top-right corner) */
539	    s_state.close_btn = lv_btn_create(s_state.screen);
540	    if (!s_state.close_btn) {
541	        syslog(LOG_ERR, "[%s] close_btn create failed\n", TAG);
542	        ret = -EIO;
543	        goto cleanup;
544	    }
545	
546	    lv_obj_set_size(s_state.close_btn, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
547	    /* Position close button inside the visible circular area.
548	     * On a 466x466 round screen (radius 233), the top-right corner
549	     * is clipped by the bezel.  Place the button at a position that
550	     * is safely inside the circle: top-center with a rightward offset.
551	     * At y=30 from top, the visible horizontal range is roughly
552	     * center ± sqrt(233²-203²) ≈ ±115px, so x offset of +80 is safe. */
553	    lv_obj_align(s_state.close_btn, LV_ALIGN_TOP_MID, 80, LVGL_UI_PADDING_TOP - 30);
554	    lv_obj_set_style_bg_opa(s_state.close_btn, LV_OPA_TRANSP, 0);
555	    lv_obj_set_style_border_width(s_state.close_btn, 0, 0);
556	    lv_obj_set_style_shadow_opa(s_state.close_btn, LV_OPA_TRANSP, 0);
557	    lv_obj_set_style_pad_all(s_state.close_btn, 8, 0);
558	
559	    lv_obj_t* close_label = lv_label_create(s_state.close_btn);
560	    if (close_label) {
561	        lv_label_set_text(close_label, CLOSE_BTN_TEXT);
562	        lv_obj_set_style_text_color(close_label, lv_color_hex(0x999999), 0);
563	        lv_obj_center(close_label);
564	    }
565	
566	    lv_obj_add_event_cb(s_state.close_btn, close_btn_event_cb, LV_EVENT_CLICKED, NULL);
567	
568	    /* Step 8: Initialize chat history and mutex */
569	    memset(&s_state.history, 0, sizeof(chat_history_t));
570	    pthread_mutex_init(&s_state.lock, NULL);
571	
572	    s_state.initialized = true;
573	    syslog(LOG_INFO, "[%s] init OK\n", TAG);
574	
575	#ifdef CONFIG_AI_AGENT_PET_STATUS
576	    /* Build the pet status ring home screen (M7 差异化页).  It is NOT loaded
577	     * here — cp_ui_main (or the AP via RPMsg) decides when to show it.  The
578	     * idle-yield timer runs in the LVGL thread and only fires when the chat
579	     * screen owns the foreground. */
580	    (void)pet_status_view_init();
581	    /* Surface the pet as the boot/home screen immediately.  On CP this is
582	     * idempotent with cp_ui_main's explicit show(); on qemu (no cp_ui_main,
583	     * no AP→CP RPMsg) it is the only thing that brings the pet up at boot. */
584	    pet_status_view_show();
585	    s_pet_idle_timer = lv_timer_create(pet_idle_timer_cb, 1000, NULL);
586	    if (s_pet_idle_timer)
587	      {
588	        lv_timer_set_repeat_count(s_pet_idle_timer, -1);
589	      }
590	    pet_idle_reset();
591	#endif
592	#ifdef CONFIG_AI_AGENT_PARTICLE_FLOW
593	    /* M7 差异化页 ②: build the particle flow screen (NOT loaded — the pet is
594	     * the cold-start home screen; the particle page is reached via set_page 1).
595	     * Init here so it is ready to show without a per-call create latency. */
596	    (void)particle_flow_view_init();
597	#endif
598	#if defined(CONFIG_AI_AGENT_PET_STATUS) && defined(CONFIG_AI_AGENT_PARTICLE_FLOW)
599	    /* Idle auto-rotate between pet ① and particle ② (UI方案.md §2.4).
600	     * 1 s period polls the idle condition; the cb self-throttles to
601	     * ROTATE_INTERVAL_MS between actual switches. */
602	    s_rotate_timer = lv_timer_create(rotate_timer_cb, 1000, NULL);
603	    if (s_rotate_timer)
604	      {
605	        lv_timer_set_repeat_count(s_rotate_timer, -1);
606	      }
607	    rotate_idle_reset();
608	#endif
609	    return 0;
610	
611	cleanup:
612	    /* Release resources in reverse order (coding-2) */
613	
614	    if (s_state.screen) {
615	        lv_obj_del(s_state.screen);
616	        s_state.screen = NULL;
617	        /* Child widgets are deleted with the screen */
618	        s_state.chat_list = NULL;
619	        s_state.ptt_btn = NULL;
620	        s_state.ptt_label = NULL;
621	        s_state.rec_indicator = NULL;
622	        s_state.close_btn = NULL;
623	    }
624	
625	    syslog(LOG_ERR, "[%s] init failed (rc=%d)\n", TAG, ret);
626	    return ret;
627	}
