652	/* Semaphore for synchronizing async stop with LVGL thread */
653	static sem_t s_stop_sem;
654	
655	/* Internal cleanup — must be called from LVGL thread context */
656	static void lvgl_ui_do_cleanup(void)
657	{
658	    int i;
659	
660	    if (s_state.screen) {
661	        /* If our screen is the active screen, restore the previous
662	         * (launcher) screen first.  Deleting the active screen without
663	         * loading another one leaves LVGL with no valid screen — the
664	         * next lv_timer_handler() call crashes with a MemManage fault
665	         * (NULL pointer dereference at offset 0x32 in lv_obj_t). */
666	        if (s_state.screen_visible && s_state.prev_screen) {
667	            lv_screen_load(s_state.prev_screen);
668	        }
669	
670	        lv_obj_del(s_state.screen);
671	        s_state.screen = NULL;
672	    }
673	
674	    s_state.screen_visible = false;
675	    s_state.prev_screen = NULL;
676	
677	    s_state.chat_list = NULL;
678	    s_state.ptt_btn = NULL;
679	    s_state.ptt_label = NULL;
680	    s_state.rec_indicator = NULL;
681	    s_state.close_btn = NULL;
682	
683	    for (i = 0; i < CHAT_HISTORY_MAX; i++) {
684	        s_state.history.msgs[i].bubble = NULL;
685	    }
686	
687	    s_state.history.head = 0;
688	    s_state.history.count = 0;
689	
690	    /* Note: when we self-initialized LVGL (s_lv_owned, qemu case), the
691	     * lv_timer_handler loop thread is intentionally left running — it is
692	     * torn down only when the ai_agent process exits.  Stopping it from
693	     * within cleanup (which itself runs in that loop thread via
694	     * lv_async_call) would self-deadlock.  Widget deletion above is safe
695	     * because the loop is still alive to process it. */
696	}
697	
698	static void stop_screen_async_cb(void* data)
699	{
700	    (void)data;
701	
702	    lvgl_ui_do_cleanup();
703	    sem_post(&s_stop_sem);
704	}
705	
706	/* Stop from within the LVGL thread (e.g. close button callback).
707	 * Performs cleanup directly — no async scheduling needed. */
708	void lvgl_ui_channel_stop_sync(void)
709	{
710	    if (!s_state.initialized || !s_state.running) {
711	        return;
712	    }
713	
714	    syslog(LOG_INFO, "[%s] stopping (sync)\n", TAG);
715	
716	    s_state.running = false;
717	    lvgl_ui_do_cleanup();
718	    pthread_mutex_destroy(&s_state.lock);
719	    s_state.initialized = false;
720	
721	    syslog(LOG_INFO, "[%s] stopped\n", TAG);
722	}
723	
724	/* Stop from an external thread (e.g. velaquit shutdown).
725	 * Schedules cleanup in the LVGL thread to avoid racing with the
726	 * miwear/launcher event loop. */
727	void lvgl_ui_channel_stop(void)
728	{
729	    /* No-op if not initialized or not running */
730	    if (!s_state.initialized || !s_state.running) {
731	        return;
732	    }
733	
734	    syslog(LOG_INFO, "[%s] stopping\n", TAG);
735	
736	    /* Mark as not running first — prevents callbacks (PTT, close_btn,
737	     * chat_view_add_message) from touching widgets during teardown. */
738	    s_state.running = false;
739	
740	    /* Schedule cleanup in the LVGL thread to avoid racing with the
741	     * miwear/launcher event loop.  Direct lv_obj_del from the
742	     * shutdown thread causes a MemManage fault because the LVGL
743	     * thread may be mid-render on the same objects. */
744	    sem_init(&s_stop_sem, 0, 0);
745	    lv_async_call(stop_screen_async_cb, NULL);
746	
747	    /* Wait for LVGL thread to complete the deletion (timeout 2s) */
748	    struct timespec ts;
749	
750	    clock_gettime(CLOCK_REALTIME, &ts);
751	    ts.tv_sec += 2;
752	
753	    if (sem_timedwait(&s_stop_sem, &ts) != 0) {
754	        syslog(LOG_WARNING,
755	            "[%s] async stop timed out, forcing cleanup\n", TAG);
756	        /* Fallback: NULL out pointers without deleting (leak is
757	         * acceptable during shutdown to avoid crash). */
758	        s_state.screen = NULL;
759	        s_state.chat_list = NULL;
760	        s_state.ptt_btn = NULL;
761	        s_state.ptt_label = NULL;
762	        s_state.rec_indicator = NULL;
763	        s_state.close_btn = NULL;
764	    }
765	
766	    sem_destroy(&s_stop_sem);
767	
768	    /* Destroy the mutex */
769	    pthread_mutex_destroy(&s_state.lock);
770	
771	    s_state.initialized = false;
772	
773	    syslog(LOG_INFO, "[%s] stopped\n", TAG);
774	}
