776	/* Async callback: load screen inside LVGL thread context */
777	static void show_screen_async_cb(void* data)
778	{
779	    (void)data;
780	    if (!s_state.initialized || !s_state.running || !s_state.screen) {
781	        return;
782	    }
783	    if (s_state.screen_visible) {
784	        return;
785	    }
786	
787	    /* CJK font selection happens at init() time via the statically-compiled
788	     * lv_font_misans_16_cjk (preferred: 3755 GB2312-1 common chars, baked into
789	     * the binary by lv_font_conv — zero runtime malloc, zero rasterization,
790	     * cannot corrupt the heap).  No runtime TTF loading here.
791	     *
792	     * History: we previously used lv_tiny_ttf_create_data() with a runtime
793	     * MiSans TTF, but stb_truetype's MakeGlyphBitmap write path overran its
794	     * output buffer on certain CJK glyphs and corrupted adjacent NuttX mm heap
795	     * chunk metadata, leading to recursive-assert reboots (mm_foreach /
796	     * nxsched_add_readytorun / nxsem_post_slow in the timer IRQ).  Subsetting
797	     * to 857 KB only delayed the crash; the root cause is the rasterizer, so
798	     * we moved to a pre-rasterized static font.  See lv_font_misans_16_cjk.c
799	     * and the fontgen notes in docs. */
800	    /* Already set in init(); nothing to do at show time. */
801	    syslog(LOG_INFO, "[%s] using static MiSans-16 CJK font\n", TAG);
802	
803	    syslog(LOG_INFO, "[%s] loading chat screen\n", TAG);
804	
805	    /* Save the current screen so we can restore it on stop.
806	     * The launcher (miwear) owns this screen — we must not delete it. */
807	    s_state.prev_screen = lv_screen_active();
808	
809	    lv_screen_load(s_state.screen);
810	    s_state.screen_visible = true;
811	
812	#ifdef LVGL_UI_CARD_SELFTEST
