818	    chat_view_add_message("Jira issue FEEDBACK-149182,经办人: 张文海,More Info", false, 0);
819	    chat_view_add_message("值得合入,建议采纳,yes", false, 0);
820	    chat_view_add_message("这是一条普通回复,用于展示默认灰色色条", false, 0);
