841	int lvgl_ui_channel_send(const char* text)
842	{
843	    int ret;
844	    async_msg_t* payload;
845	
846	    /* Parameter validation: NULL or empty string */
847	    if (!text || text[0] == '\0') {
848	        syslog(LOG_ERR, "[%s] send: invalid text (NULL or empty)\n", TAG);
849	        return -EINVAL;
850	    }
851	
852	    /* Check channel readiness */
853	    if (!s_state.initialized || !s_state.running) {
854	        syslog(LOG_ERR, "[%s] send: channel not ready (init=%d run=%d)\n",
855	            TAG, s_state.initialized, s_state.running);
856	        return -EINVAL;
857	    }
858	
859	    /* Auto-show chat screen on first Agent reply */
860	    if (!s_state.screen_visible) {
861	        lvgl_ui_channel_show();
862	    }
863	
864	    /* Schedule bubble creation in LVGL thread via lv_async_call.
865	     * This avoids the "Invalidate area is not allowed during rendering"
866	     * assertion crash that occurs when we create LVGL widgets from
867	     * the agent dispatch thread while miwear's LVGL thread is
868	     * mid-render. */
869	    payload = malloc(sizeof(async_msg_t));
870	    if (!payload) {
871	        syslog(LOG_ERR, "[%s] send: async payload alloc failed\n", TAG);
872	        return -ENOMEM;
873	    }
874	
875	    chat_view_copy_text(payload->text, text, LVGL_UI_MSG_MAX_LEN);
876	    payload->is_user = false;
877	
878	    lv_async_call(chat_view_add_message_async_cb, payload);
879	
880	    /* TTS is blocking — run after scheduling the UI update */
881	    ret = voice_channel_speak(text);
882	    if (ret != 0) {
883	        syslog(LOG_ERR, "[%s] voice_channel_speak failed (rc=%d)\n", TAG, ret);
884	    }
885	
886	    return 0;
887	}
