955	/* ── External PTT state (AP→CP RPMsg SET_PTT) ─────────────────── */
956	
957	/* Heap-allocated state for async set_ptt (single int fits in a void* but
958	 * keep a small struct for clarity/future fields). */
959	typedef struct {
960	    int state;
961	} async_ptt_t;
962	
963	static void set_ptt_async_cb(void* data)
964	{
965	    async_ptt_t* p = (async_ptt_t*)data;
966	    if (!p) {
967	        return;
968	    }
969	    if (!s_state.initialized || !s_state.running) {
970	        free(p);
971	        return;
972	    }
973	
974	    switch (p->state) {
975	    case LVGL_UI_PTT_RECORDING:
976	        s_state.is_recording = true;
977	        s_state.is_processing = false;
978	        recording_indicator_start();
979	#ifdef CONFIG_AI_AGENT_PET_STATUS
980	        /* Mirror PTT onto the pet: a recording session reads as "listening". */
981	        pet_status_view_set_state(PET_STATE_LISTENING);
982	#endif
983	        break;
984	    case LVGL_UI_PTT_PROCESSING:
985	        s_state.is_recording = false;
986	        s_state.is_processing = true;
987	        recording_indicator_show_processing();
988	#ifdef CONFIG_AI_AGENT_PET_STATUS
989	        pet_status_view_set_state(PET_STATE_THINKING);
990	#endif
991	        break;
992	    case LVGL_UI_PTT_IDLE:
993	    default:
994	        s_state.is_recording = false;
995	        s_state.is_processing = false;
996	        recording_indicator_stop();
997	#ifdef CONFIG_AI_AGENT_PET_STATUS
998	        pet_status_view_set_state(PET_STATE_IDLE);
999	#endif
1000	        break;
1001	    }
1002	    free(p);
1003	}
1004	
1005	int lvgl_ui_channel_set_ptt(int state)
1006	{
1007	    async_ptt_t* payload;
1008	
1009	    if (!s_state.initialized || !s_state.running) {
1010	        return -EINVAL;
1011	    }
1012	    /* Coerce unknown values to IDLE. */
1013	    if (state != LVGL_UI_PTT_IDLE && state != LVGL_UI_PTT_RECORDING &&
1014	        state != LVGL_UI_PTT_PROCESSING) {
1015	        state = LVGL_UI_PTT_IDLE;
1016	    }
1017	
1018	    payload = malloc(sizeof(async_ptt_t));
1019	    if (!payload) {
1020	        syslog(LOG_ERR, "[%s] set_ptt: payload alloc failed\n", TAG);
1021	        return -ENOMEM;
1022	    }
1023	    payload->state = state;
1024	    lv_async_call(set_ptt_async_cb, payload);
1025	    return 0;
1026	}
