1042	    /* Mirror the agent state onto the particle page too: when the particle
1043	     * page is visible its color/flow tracks the same lifecycle; when hidden
1044	     * this just stages the color for the next show. */
1045	    particle_flow_view_set_state((enum particle_state)state);
1046	    rc = 0;
1047	#endif
1048	    (void)rc;
1049	    if (state != s_last_pet_state)
1050	      {
1051	        s_last_pet_state = state;
1052	        rotate_idle_reset();   /* state change restarts the idle-rotate countdown */
1053	      }
