1058	 * page 0 → pet home screen, page 1 → particle flow.  The chat screen is
1059	 * intentionally excluded — it auto-preempts on send/send_user and yields back
1060	 * to the pet on idle.  Dispatched async on the LVGL thread. */
1061	int lvgl_ui_channel_set_page(int page)
1062	{
