1068	#ifdef CONFIG_AI_AGENT_PARTICLE_FLOW
1069	          particle_flow_view_hide();
1070	#endif
1071	          pet_status_view_show();
1072	          return 0;
1073	#else
1074	          return -ENOSYS;
1075	#endif
1076	        case 1:
1077	#ifdef CONFIG_AI_AGENT_PARTICLE_FLOW
1078	#ifdef CONFIG_AI_AGENT_PET_STATUS
1079	          pet_status_view_hide();
1080	#endif
1081	          particle_flow_view_show();
1082	          return 0;
1083	#else
