1093	/* Called by lv_timer_handler() inside the LVGL thread.
1094	 * Safe to create/modify LVGL objects here. */
1095	static void chat_view_add_message_async_cb(void* data)
1096	{
1097	    async_msg_t* payload = (async_msg_t*)data;
1098	
1099	    if (!payload) {
1100	        return;
1101	    }
1102	
1103	    if (!s_state.initialized || !s_state.running) {
1104	        free(payload);
1105	        return;
1106	    }
1107	
1108	    /* A new chat message resets the pet-yield idle timer (the conversation
1109	     * is alive).  No-op when PET_STATUS is off. */
1110	    pet_idle_reset();
1111	
1112	    chat_view_add_message(payload->text, payload->is_user, payload->bar_color);
1113	    free(payload);
1114	    payload = NULL;
1115	}
