1119	/* Classify an Agent reply text into a coarse card category so the
1120	 * left color bar gives a glanceable cue.  Matching is intentionally
1121	 * simple (case-insensitive substring) — this is a visual hint, not
1122	 * a parser.  Returns the palette color for the matched category. */
1123	static uint32_t chat_view_classify_reply(const char* text)
1124	{
1125	    if (!text || !*text) {
1126	        return LVGL_UI_CARD_COLOR_PLAIN;
1127	    }
1128	
1129	    /* Build a lowercase copy (ASCII only; CJK passes through untouched)
1130	     * so substring checks are case-insensitive for the latin keywords. */
1131	    char buf[LVGL_UI_MSG_MAX_LEN];
1132	    size_t i;
1133	    for (i = 0; i < sizeof(buf) - 1 && text[i]; i++) {
1134	        buf[i] = (text[i] >= 'A' && text[i] <= 'Z') ? (text[i] + 32) : text[i];
1135	    }
1136	    buf[i] = '\0';
1137	
1138	    /* Conclusion: explicit yes/no or recommendation phrasing */
1139	    if (strstr(buf, "yes") || strstr(buf, " no") || strstr(buf, "no.") ||
1140	        strstr(buf, "no,") || strstr(buf, "\xe5\x80\xbc\xe5\xbe\x97") /* 值得 */ ||
1141	        strstr(buf, "\xe4\xb8\x8d\xe5\xbb\xba\xe8\xae\xae") /* 不建议 */ ||
1142	        strstr(buf, "\xe5\xbb\xba\xe8\xae\xae") /* 建议 */ ) {
1143	        return LVGL_UI_CARD_COLOR_CONCLUSION;
1144	    }
1145	
1146	    /* Structured: Gerrit change status keywords (latin) or 状态: */
1147	    if (strstr(buf, "merged") || strstr(buf, "abandoned") ||
1148	        strstr(buf, "status:") || strstr(buf, "\xe7\x8a\xb6\xe6\x80\x81") /* 状态 */ ) {
1149	        return LVGL_UI_CARD_COLOR_STRUCTURED;
1150	    }
1151	
1152	    /* Jira: workflow status or assignee fields */
1153	    if (strstr(buf, "more info") || strstr(buf, "assignee") ||
1154	        strstr(buf, "\xe7\xbb\x8f\xe5\x8a\x9e\xe4\xba\xba") /* 经办人 */ ||
1155	        strstr(buf, "jira") ) {
1156	        return LVGL_UI_CARD_COLOR_JIRA;
1157	    }
1158	
1159	    return LVGL_UI_CARD_COLOR_PLAIN;
1160	}
