1253	static void chat_view_add_message(const char* text, bool is_user,
1254	                                  uint32_t bar_color)
1255	{
1256	    chat_history_t* h = &s_state.history;
1257	    chat_msg_t* slot;
1258	    lv_obj_t* bubble;
1259	    lv_obj_t* lbl;
1260	
1261	    /* If history is already full, trim before overwriting */
1262	    if (h->count == CHAT_HISTORY_MAX) {
1263	        chat_view_trim_history();
1264	    }
1265	
1266	    /* Store message in ring buffer (handles truncation + old bubble deletion) */
1267	    slot = chat_history_add(h, text, is_user);
1268	
1269	    /* Create bubble container inside chat_list */
1270	    bubble = lv_obj_create(s_state.chat_list);
1271	    if (!bubble) {
1272	        syslog(LOG_ERR, "[%s] bubble create failed\n", TAG);
1273	        return;
1274	    }
1275	
1276	    lv_obj_set_width(bubble, lv_pct(85));
1277	    lv_obj_set_height(bubble, LV_SIZE_CONTENT);
1278	    lv_obj_set_style_radius(bubble, LVGL_UI_BUBBLE_RADIUS, 0);
1279	    lv_obj_set_style_pad_all(bubble, LVGL_UI_BUBBLE_PAD, 0);
1280	    lv_obj_set_style_border_width(bubble, 0, 0);
1281	
1282	    if (is_user) {
1283	        /* User bubble: right-aligned, blue background, white text */
1284	        lv_obj_set_style_align(bubble, LV_ALIGN_RIGHT_MID, 0);
1285	        lv_obj_set_style_bg_color(bubble, lv_color_hex(0x3a7bd5), 0);
1286	        lv_obj_set_style_text_color(bubble, lv_color_white(), 0);
1287	    } else {
1288	        /* Agent card: left-aligned, semi-transparent dark bg, vertical
1289	         * flex layout so title bar / divider / body stack top-to-bottom. */
1290	        lv_obj_set_style_align(bubble, LV_ALIGN_LEFT_MID, 0);
1291	        /* Card bg lighter than the screen bg (0x1a1a2e) + thin border so
1292	         * the card reads as a distinct rounded box instead of blending
1293	         * invisibly into the dark background. */
1294	        lv_obj_set_style_bg_color(bubble, lv_color_hex(0x363650), 0);
1295	        lv_obj_set_style_bg_opa(bubble, LV_OPA_COVER, 0);
1296	        lv_obj_set_style_border_color(bubble, lv_color_hex(0x4a4a66), 0);
1297	        lv_obj_set_style_border_width(bubble, 1, 0);
1298	        lv_obj_set_style_text_color(bubble, lv_color_hex(0xe8e8e8), 0);
1299	        lv_obj_set_flex_flow(bubble, LV_FLEX_FLOW_COLUMN);
1300	        lv_obj_set_flex_align(bubble, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_START,
1301	                              LV_FLEX_ALIGN_START);
1302	        lv_obj_set_style_pad_row(bubble, LVGL_UI_CARD_GAP, 0);
1303	    }
1304	
1305	    if (is_user) {
1306	        /* User bubble: plain label */
1307	        lbl = lv_label_create(bubble);
1308	        if (!lbl) {
1309	            syslog(LOG_ERR, "[%s] bubble label create failed\n", TAG);
1310	            lv_obj_del(bubble);
1311	            slot->bubble = NULL;
1312	            return;
1313	        }
1314	
1315	        lv_label_set_text(lbl, slot->text);
1316	        lv_label_set_long_mode(lbl, LV_LABEL_LONG_WRAP);
1317	        lv_obj_set_width(lbl, lv_pct(100));
1318	    } else {
1319	        /* Agent bubble: enhanced card (title bar + divider + color bar + body) */
1320	        uint32_t color = bar_color ? bar_color : chat_view_classify_reply(slot->text);
1321	        chat_view_build_agent_card(bubble, slot->text, color);
1322	    }
1323	
1324	    slot->bubble = bubble;
1325	
1326	    chat_view_scroll_to_bottom();
1327	}
