1341	static void ptt_btn_event_cb(lv_event_t* e)
1342	{
1343	    lv_event_code_t code = lv_event_get_code(e);
1344	
1345	    /* Single-click toggle: first click starts recording, second stops */
1346	    if (code != LV_EVENT_CLICKED) {
1347	        return;
1348	    }
1349	
1350	    pthread_mutex_lock(&s_state.lock);
1351	
1352	    if (s_state.is_processing) {
1353	        pthread_mutex_unlock(&s_state.lock);
1354	        return;
1355	    }
1356	
1357	    if (!s_state.is_recording) {
1358	        /* First click: start recording */
1359	        int ret = voice_channel_start();
1360	        if (ret != 0) {
1361	            syslog(LOG_ERR, "[%s] voice_channel_start failed (rc=%d)\n", TAG, ret);
1362	            pthread_mutex_unlock(&s_state.lock);
1363	            chat_view_add_message("录音启动失败", false, 0);
1364	            return;
1365	        }
1366	
1367	        s_state.is_recording = true;
1368	        pthread_mutex_unlock(&s_state.lock);
1369	
1370	        recording_indicator_start();
1371	    } else {
1372	        /* Second click: stop recording and process */
1373	        s_state.is_recording = false;
1374	        s_state.is_processing = true;
1375	        pthread_mutex_unlock(&s_state.lock);
1376	
1377	        recording_indicator_show_processing();
1378	
1379	        /* Stop recording and get ASR text synchronously */
1380	        char asr_text[LVGL_UI_MSG_MAX_LEN];
1381	        int ret = voice_channel_stop_with_text(asr_text,
1382	            sizeof(asr_text));
1383	
1384	        if (ret != 0) {
1385	            syslog(LOG_ERR,
1386	                "[%s] voice_channel_stop_with_text failed (rc=%d)\n",
1387	                TAG, ret);
1388	            goto done;
1389	        }
1390	
1391	        if (asr_text[0] == '\0') {
1392	            chat_view_add_message("未识别到语音", false, 0);
1393	            goto done;
1394	        }
1395	
1396	        /* Route through the single dispatch point so the destination stays
1397	         * out of this file: with no sink registered the utterance goes to the
1398	         * chat bus exactly as before, and a product that registered one owns
1399	         * it instead.  This file must not learn which consumer exists.
1400	         */
1401	
1402	        voice_channel_dispatch(asr_text);
1403	        chat_view_add_message(asr_text, true, 0);
1404	
1405	    done:
1406	        pthread_mutex_lock(&s_state.lock);
1407	        s_state.is_processing = false;
1408	        pthread_mutex_unlock(&s_state.lock);
1409	        recording_indicator_stop();
1410	    }
1411	}
