1413	/* Close button callback — destroy chat screen and stop audio */
1414	static void close_btn_event_cb(lv_event_t* e)
1415	{
1416	    (void)e;
1417	    if (!s_state.initialized || !s_state.running) {
1418	        return;
1419	    }
1420	
1421	    syslog(LOG_INFO, "[%s] chat screen closed by user\n", TAG);
1422	
1423	    /* Stop any active recording first */
1424	    if (s_state.is_recording) {
1425	        voice_channel_stop();
1426	        s_state.is_recording = false;
1427	    }
1428	
1429	    /* Full teardown: destroy screen, free font, reset state.
1430	     * Use sync version — we are already in the LVGL thread. */
1431	    lvgl_ui_channel_stop_sync();
1432	}
