90	/* ---------- animation exec callbacks (LVGL v9: (obj, value)) ---------- */
91	
92	/* LVGL v9 exec_cb signature is lv_anim_exec_xcb_t = void(*)(void*, lv_anim_value_t),
93	 * i.e. the first arg is the animated var (void*), NOT lv_obj_t* nor lv_anim_t*.
94	 * We cast to lv_obj_t* inside for the lv_obj and lv_arc calls. */
95	/* Spinner: a 90° segment rotating (THINKING / LISTENING). value = start angle. */
96	static void spin_cb(void *obj, int32_t v)
97	{
98	  lv_obj_t *o = (lv_obj_t *)obj;
99	  lv_arc_set_angles(o, v, v + 90);
100	}
101	
102	/* Growing fill: indicator grows 0→360 (EXECUTING). value = end angle. */
103	static void fill_cb(void *obj, int32_t v)
104	{
105	  lv_obj_t *o = (lv_obj_t *)obj;
106	  lv_arc_set_angles(o, 0, v);
107	}
108	
109	/* Breathing: face opacity pulses (IDLE). value 0..100. */
110	static void breathe_cb(void *obj, int32_t v)
111	{
112	  lv_obj_t *o = (lv_obj_t *)obj;
113	  /* 100% → 255, 0% → 190 (gentle). */
114	  lv_obj_set_style_opa(o, LV_OPA_COVER - (v * (LV_OPA_COVER - 190)) / 100, 0);
115	}
116	
117	/* Blink: both eyes opacity (WAITING). value 0..100, triangle-ish via sin-free. */
118	static void blink_cb(void *obj, int32_t v)
119	{
120	  lv_obj_t *o = (lv_obj_t *)obj;
121	  /* open(0) → closed(50) → open(100): opaque at ends, transparent at mid. */
122	  lv_opa_t op = (v < 50) ? LV_OPA_COVER - (v * 2)
123	                       : LV_OPA_TRANSP + ((v - 50) * 2 * LV_OPA_COVER / 100);
124	  if (op > LV_OPA_COVER) op = LV_OPA_COVER;
125	  lv_obj_set_style_opa(o, op, 0);
126	}
127	
128	/* Shake: face x jitter (ERROR). value 0..100 maps to a few oscillations. */
129	static void shake_cb(void *obj, int32_t v)
130	{
131	  lv_obj_t *o = (lv_obj_t *)obj;
132	  /* 0..100 → four half-swings of ±5px. Simple triangle per 25-step. */
133	  int seg = v / 25;
134	  int phase = v % 25;
135	  int amp = (phase < 13) ? (phase * 5 / 12) : ((25 - phase) * 5 / 12);
136	  int sign = (seg % 2 == 0) ? 1 : -1;
137	  lv_obj_set_style_translate_x(o, sign * amp, 0);
138	}
139	
140	static void stop_anim(void)
141	{
142	  /* Delete any anim bound to our widgets. lv_anim_delete is a no-op if none. */
143	  if (s_pet.ring)  lv_anim_delete(s_pet.ring,  spin_cb);
144	  if (s_pet.face)  lv_anim_delete(s_pet.face,  breathe_cb);
145	  if (s_pet.face)  lv_anim_delete(s_pet.face,  shake_cb);
146	  if (s_pet.eye_l) lv_anim_delete(s_pet.eye_l, blink_cb);
147	  if (s_pet.eye_r) lv_anim_delete(s_pet.eye_r, blink_cb);
148	  s_pet.anim_active = false;
149	}
150	
151	/* Position pupils within eyes according to state. */
152	static void apply_pupils(enum pet_state st)
153	{
154	  int dx = 0, dy = 0;            /* pupil offset from eye center */
155	  lv_opa_t eye_opa = LV_OPA_COVER;
156	  switch (st)
157	    {
158	      case PET_STATE_THINKING:  dy = -3; break;             /* look up */
159	      case PET_STATE_LISTENING: dy = 3;  break;              /* look down */
160	      case PET_STATE_EXECUTING: dx = 0;  dy = 0; break;      /* focused */
161	      case PET_STATE_WAITING:   /* blink handled by anim; pupils normal */
162	      case PET_STATE_IDLE:      dx = 0;  dy = 0; break;
163	      case PET_STATE_ERROR:     dx = 3;  dy = -3; eye_opa = LV_OPA_60; break;
164	      default: break;
165	    }
166	  if (s_pet.pupil_l) lv_obj_align(s_pet.pupil_l, LV_ALIGN_CENTER, -dx, dy);
167	  if (s_pet.pupil_r) lv_obj_align(s_pet.pupil_r, LV_ALIGN_CENTER,  dx, dy);
168	  /* For ERROR, dim eyes a touch so the "X" feel reads (pupils at corners). */
169	  if (s_pet.eye_l) lv_obj_set_style_opa(s_pet.eye_l, eye_opa, 0);
170	  if (s_pet.eye_r) lv_obj_set_style_opa(s_pet.eye_r, eye_opa, 0);
171	}
172	
173	static void start_anim_for(enum pet_state st)
174	{
175	  lv_anim_t a;
176	  uint32_t color = s_state_color[st];
177	
178	  stop_anim();
179	  if (!s_pet.ring || !s_pet.face) return;
180	
181	  /* Ring color always tracks state; base angles reset per effect. */
182	  lv_obj_set_style_arc_color(s_pet.ring, lv_color_hex(color), 0);
183	
184	  switch (st)
185	    {
186	      case PET_STATE_THINKING:
187	      case PET_STATE_LISTENING:
188	        lv_anim_init(&a);
189	        lv_anim_set_var(&a, s_pet.ring);
190	        lv_anim_set_values(&a, 0, 360);
191	        lv_anim_set_time(&a, 1400);
192	        lv_anim_set_exec_cb(&a, spin_cb);
193	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
194	        lv_anim_start(&a);
195	        break;
196	      case PET_STATE_EXECUTING:
197	        lv_anim_init(&a);
198	        lv_anim_set_var(&a, s_pet.ring);
199	        lv_anim_set_values(&a, 0, 360);
200	        lv_anim_set_time(&a, 900);
201	        lv_anim_set_exec_cb(&a, fill_cb);
202	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
203	        lv_anim_start(&a);
204	        break;
205	      case PET_STATE_IDLE:
206	        lv_anim_init(&a);
207	        lv_anim_set_var(&a, s_pet.face);
208	        lv_anim_set_values(&a, 0, 100);
209	        lv_anim_set_time(&a, 1800);
210	        lv_anim_set_exec_cb(&a, breathe_cb);
211	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
212	        lv_anim_start(&a);
213	        lv_arc_set_angles(s_pet.ring, 0, 360);  /* full ring */
214	        break;
215	      case PET_STATE_WAITING:
216	        lv_anim_init(&a);
217	        lv_anim_set_var(&a, s_pet.eye_l);
218	        lv_anim_set_values(&a, 0, 100);
219	        lv_anim_set_time(&a, 700);
220	        lv_anim_set_exec_cb(&a, blink_cb);
221	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
222	        lv_anim_start(&a);
223	        lv_anim_init(&a);
224	        lv_anim_set_var(&a, s_pet.eye_r);
225	        lv_anim_set_values(&a, 0, 100);
226	        lv_anim_set_time(&a, 700);
227	        lv_anim_set_exec_cb(&a, blink_cb);
228	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
229	        lv_anim_start(&a);
230	        lv_arc_set_angles(s_pet.ring, 0, 360);
231	        break;
232	      case PET_STATE_ERROR:
233	        lv_anim_init(&a);
234	        lv_anim_set_var(&a, s_pet.face);
235	        lv_anim_set_values(&a, 0, 100);
236	        lv_anim_set_time(&a, 350);
237	        lv_anim_set_exec_cb(&a, shake_cb);
238	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
239	        lv_anim_start(&a);
240	        lv_arc_set_angles(s_pet.ring, 0, 360);
241	        break;
242	      default:
243	        lv_arc_set_angles(s_pet.ring, 0, 360);
244	        break;
245	    }
246	  s_pet.anim_active = true;
247	}
