249	/* ---------- async apply (runs in LVGL thread) ---------- */
250	
251	static void apply_state_async_cb(void *data)
252	{
253	  enum pet_state st = (enum pet_state)(intptr_t)data;
254	  if (!s_pet.initialized || !s_pet.face) return;
255	
256	  s_pet.state = st;
257	  uint32_t color = s_state_color[st];
258	
259	  lv_obj_set_style_bg_color(s_pet.face, lv_color_hex(color), 0);
260	  lv_obj_set_style_bg_opa(s_pet.face, LV_OPA_COVER, 0);
261	  lv_obj_set_style_translate_x(s_pet.face, 0, 0);  /* clear any shake offset */
262	  lv_obj_set_style_opa(s_pet.face, LV_OPA_COVER, 0);
263	
264	  if (s_pet.label) lv_label_set_text(s_pet.label, s_state_text[st]);
265	
266	  apply_pupils(st);
267	  start_anim_for(st);
268	  syslog(LOG_INFO, "[%s] state → %s\n", TAG, s_state_text[st]);
269	}
270	
271	void pet_status_view_set_state(enum pet_state state)
272	{
273	  if ((int)state < 0 || (int)state > PET_STATE_ERROR) return;
274	  /* Async: widget mutation must happen in the LVGL thread. */
275	  lv_async_call(apply_state_async_cb, (void *)(intptr_t)state);
276	}
