278	/* ---------- screen show / hide ---------- */
279	
280	static void show_async_cb(void *data)
281	{
282	  (void)data;
283	  if (!s_pet.initialized || !s_pet.screen || s_pet.visible) return;
284	  s_pet.prev_screen = lv_screen_active();
285	  lv_screen_load(s_pet.screen);
286	  s_pet.visible = true;
287	  /* Re-assert current state's animation (lv_anim may have been paused off-screen). */
288	  start_anim_for(s_pet.state);
289	  syslog(LOG_INFO, "[%s] pet screen shown\n", TAG);
290	}
