321	static lv_obj_t *make_circle(lv_obj_t *parent, int32_t size,
322	                              uint32_t color, lv_opa_t opa)
323	{
324	  lv_obj_t *o = lv_obj_create(parent);
325	  if (!o) return NULL;
326	  lv_obj_remove_style_all(o);
327	  lv_obj_set_size(o, size, size);
328	  lv_obj_set_style_radius(o, LV_RADIUS_CIRCLE, 0);
329	  lv_obj_set_style_bg_color(o, lv_color_hex(color), 0);
330	  lv_obj_set_style_bg_opa(o, opa, 0);
331	  lv_obj_set_style_border_width(o, 0, 0);
332	  lv_obj_center(o);
333	  return o;
334	}
