336	int pet_status_view_init(void)
337	{
338	  if (s_pet.initialized) return 0;
339	
340	  memset(&s_pet, 0, sizeof(s_pet));
341	  s_pet.state = PET_STATE_IDLE;
342	
343	  s_pet.screen = lv_obj_create(NULL);
344	  if (!s_pet.screen) return -ENOMEM;
345	  lv_obj_set_style_bg_color(s_pet.screen, lv_color_hex(0x1a1a2e), 0);
346	  lv_obj_set_style_bg_opa(s_pet.screen, LV_OPA_COVER, 0);
347	  lv_obj_set_style_text_font(s_pet.screen, &lv_font_misans_16_cjk, 0);
348	
349	  /* Ring (arc) — centered, then face centered on top of it. */
350	  s_pet.ring = lv_arc_create(s_pet.screen);
351	  if (s_pet.ring)
352	    {
353	      lv_obj_set_size(s_pet.ring, PET_RING_SIZE, PET_RING_SIZE);
354	      lv_obj_center(s_pet.ring);
355	      lv_arc_set_rotation(s_pet.ring, 0);
356	      lv_arc_set_bg_angles(s_pet.ring, 0, 360);
357	      lv_arc_set_angles(s_pet.ring, 0, 360);
358	      lv_arc_set_range(s_pet.ring, 0, 360);
359	      lv_obj_set_style_arc_width(s_pet.ring, 4, 0);
360	      lv_obj_set_style_arc_width(s_pet.ring, 4, LV_PART_MAIN);
361	      lv_obj_set_style_arc_color(s_pet.ring, lv_color_hex(0x2a2a3e), LV_PART_MAIN);
362	      lv_obj_set_style_arc_color(s_pet.ring, lv_color_hex(0x4ade80), 0);
363	      lv_obj_set_style_arc_rounded(s_pet.ring, true, 0);
364	      lv_obj_set_style_arc_rounded(s_pet.ring, true, LV_PART_MAIN);
365	      lv_obj_remove_flag(s_pet.ring, LV_OBJ_FLAG_CLICKABLE);
366	      /* Hide the arc knob. */
367	      lv_obj_set_style_bg_opa(s_pet.ring, LV_OPA_TRANSP, LV_PART_KNOB);
368	    }
369	
370	  /* Face. */
371	  s_pet.face = make_circle(s_pet.screen, PET_FACE_SIZE, 0x4ade80, LV_OPA_COVER);
372	  if (!s_pet.face) goto fail;
373	
374	  /* Eyes (white) — children of face so they move with it. */
375	  s_pet.eye_l = make_circle(s_pet.face, PET_EYE_R * 2, 0xffffff, LV_OPA_COVER);
376	  if (s_pet.eye_l) lv_obj_align(s_pet.eye_l, LV_ALIGN_CENTER, -PET_EYE_DX, PET_EYE_DY);
377	  s_pet.eye_r = make_circle(s_pet.face, PET_EYE_R * 2, 0xffffff, LV_OPA_COVER);
378	  if (s_pet.eye_r) lv_obj_align(s_pet.eye_r, LV_ALIGN_CENTER,  PET_EYE_DX, PET_EYE_DY);
379	
380	  /* Pupils (dark) — children of eyes. */
381	  s_pet.pupil_l = make_circle(s_pet.eye_l, PET_PUPIL_R * 2, 0x101020, LV_OPA_COVER);
382	  s_pet.pupil_r = make_circle(s_pet.eye_r, PET_PUPIL_R * 2, 0x101020, LV_OPA_COVER);
383	
384	  /* Status label below the face. */
385	  s_pet.label = lv_label_create(s_pet.screen);
386	  if (s_pet.label)
387	    {
388	      lv_label_set_text(s_pet.label, s_state_text[PET_STATE_IDLE]);
389	      lv_obj_set_style_text_color(s_pet.label, lv_color_hex(0xcccccc), 0);
390	      lv_obj_set_style_text_font(s_pet.label, &lv_font_misans_16_cjk, 0);
391	      lv_obj_align(s_pet.label, LV_ALIGN_CENTER, 0, PET_LABEL_DY);
392	    }
393	
394	  s_pet.initialized = true;
395	  syslog(LOG_INFO, "[%s] init OK (圆屏宠物状态环)\n", TAG);
396	  return 0;
397	
398	fail:
399	  if (s_pet.screen) lv_obj_del(s_pet.screen);
400	  memset(&s_pet, 0, sizeof(s_pet));
401	  return -ENOMEM;
402	}
