86	struct particle_s {
87	  int32_t x, y;          /* position, pixels */
88	  int32_t vx, vy;        /* velocity, q8 (256 = 1px/tick) */
89	  uint32_t lcg;          /* per-particle pseudo-noise state */
90	  int32_t last_rx, last_ry;  /* last rendered top-left; skip set_pos if unchanged */
91	};
