93	struct pf_state_s {
94	  bool initialized;
95	  bool visible;
96	  enum particle_state state;
97	  lv_obj_t *screen;
98	  lv_obj_t *guide_ring;  /* faint lv_arc, shared motif with pet */
99	  lv_obj_t *core;        /* central pulsing circle */
100	  lv_obj_t *particles[N_PARTICLES];
101	  lv_obj_t *label;
102	  lv_obj_t *prev_screen;
103	  struct particle_s p[N_PARTICLES];
104	  lv_timer_t *timer;
105	  uint32_t tick;
106	  /* display geometry (pixels) */
107	  int32_t cx, cy, R, R_sq;
108	};
109	
110	static struct pf_state_s s_pf;
111	
112	/* ---------- LCG (per-particle deterministic pseudo-noise) ---------- */
113	
114	static inline int32_t lcg_next(uint32_t *s)
115	{
116	  *s = (*s * 1103515765u + 12345u) & 0x7fffffffu;
117	  return (int32_t)(*s >> 15) - 16384;   /* [-16384, 16383] */
118	}
119	
120	/* ---------- physics step (runs in LVGL thread via timer) ---------- */
121	
122	static void physics_step(void)
123	{
124	  const phys_t *ph = &s_phys[s_pf.state];
125	  int32_t cx = s_pf.cx, cy = s_pf.cy, R_sq = s_pf.R_sq;
126	  int32_t damp = ph->damp;
127	  int32_t perturb = ph->perturb;
128	  int32_t swirl = ph->swirl;
129	  int32_t radial = ph->radial;
130	
131	  for (int i = 0; i < N_PARTICLES; i++)
132	    {
133	      struct particle_s *p = &s_pf.p[i];
134	      int32_t dx = p->x - cx;
135	      int32_t dy = p->y - cy;
136	
137	      /* LCG noise → small velocity kick (perturb in q8; noise normalized to ~[-1,1] px). */
138	      int32_t nx = lcg_next(&p->lcg);
139	      int32_t ny = lcg_next(&p->lcg);
140	      p->vx += (nx * perturb) / 16384;
141	      p->vy += (ny * perturb) / 16384;
142	
143	      /* Swirl: tangential bias ∝ radial offset (unnormalized → faster swirl
144	       * farther out, reads as rotation). tang = (-dy, dx). */
145	      p->vx += (-dy * swirl) / 64;
146	      p->vy += ( dx * swirl) / 64;
147	
148	      /* Radial bias: outward (+) pulls particles to the rim, inward (-) sucks
149	       * them toward the core. */
150	      p->vx += (dx * radial) / 64;
151	      p->vy += (dy * radial) / 64;
152	
153	      /* Damping. */
154	      p->vx = (p->vx * damp) / 256;
155	      p->vy = (p->vy * damp) / 256;
156	
157	      /* Speed clamp so chaos stays bounded. */
158	      int32_t vmax = 3 * ONE_PX;
159	      if (p->vx >  vmax) p->vx =  vmax;
160	      if (p->vx < -vmax) p->vx = -vmax;
161	      if (p->vy >  vmax) p->vy =  vmax;
162	      if (p->vy < -vmax) p->vy = -vmax;
163	
164	      /* Advance. */
165	      int32_t nxp = p->x + (p->vx >> VEL_Q);
166	      int32_t nyp = p->y + (p->vy >> VEL_Q);
167	
168	      /* Round-bound bounce: if next step leaves the disc, reverse velocity
169	       * (cheap reflection) and don't move this tick. dist_sq in pixel units
170	       * fits in int32 (max ~217k). */
171	      int32_t ddx = nxp - cx;
172	      int32_t ddy = nyp - cy;
173	      int32_t dsq = ddx * ddx + ddy * ddy;
174	      if (dsq > R_sq)
175	        {
176	          p->vx = -p->vx;
177	          p->vy = -p->vy;
178	        }
179	      else
180	        {
181	          p->x = nxp;
182	          p->y = nyp;
183	        }
184	
185	      /* Render — only invalidate when the integer pixel position actually
186	       * changes.  Particles move sub-pixel most ticks (q8 velocity), so an
187	       * unconditional set_pos would invalidate 18 regions every 33 ms even
188	       * when nothing visibly moved.  On flush paths that can't keep up
189	       * (qemu goldfish headless fb) the constant re-invalidation starves the
190	       * flush so the screen never reaches the framebuffer.  Skipping no-op
191	       * moves collapses invalidations to only real pixel crossings. */
192	      lv_obj_t *o = s_pf.particles[i];
193	      if (o)
194	        {
195	          int32_t rx = p->x - (PARTICLE_DIAM / 2);
196	          int32_t ry = p->y - (PARTICLE_DIAM / 2);
197	          if (rx != p->last_rx || ry != p->last_ry)
198	            {
199	              lv_obj_set_pos(o, rx, ry);
200	              p->last_rx = rx;
201	              p->last_ry = ry;
202	            }
203	        }
204	    }
205	
206	  /* Core pulse: opacity breathing driven by tick (no lv_anim to keep the
207	   * pulsing phase-locked to the physics tick). */
208	  if (s_pf.core)
209	    {
210	      uint32_t t = s_pf.tick & 63;            /* 0..63 */
211	      int32_t tri = (t < 32) ? t : (63 - t);  /* triangle 0..31 */
212	      lv_opa_t opa = LV_OPA_60 + (tri * (LV_OPA_COVER - LV_OPA_60)) / 31;
213	      lv_obj_set_style_opa(s_pf.core, opa, 0);
214	    }
215	
216	  s_pf.tick++;
217	}
