265	static void show_async_cb(void *data)
266	{
267	  (void)data;
268	  if (!s_pf.initialized || !s_pf.screen || s_pf.visible) return;
269	  s_pf.prev_screen = lv_screen_active();
270	  lv_screen_load(s_pf.screen);
271	  /* Re-assert bg + force a synchronous refresh so the secondary (async-loaded)
272	   * screen flushes immediately.  The boot/home pet screen is flushed during
273	   * lvgl_ui_channel_init; a page-switched-in screen needs the explicit nudge
274	   * or its first frame can be skipped by lazy flush paths. */
275	  lv_obj_set_style_bg_color(s_pf.screen, lv_color_hex(0x1a1a2e), 0);
276	  lv_obj_set_style_bg_opa(s_pf.screen, LV_OPA_COVER, 0);
277	  lv_obj_invalidate(s_pf.screen);
278	  lv_refr_now(lv_display_get_default());
279	  s_pf.visible = true;
280	  syslog(LOG_INFO, "[%s] particle screen shown\n", TAG);
281	}
