309	/* ---------- init ---------- */
310	
311	static lv_obj_t *make_circle(lv_obj_t *parent, int32_t diam,
312	                              uint32_t color, lv_opa_t opa)
313	{
314	  lv_obj_t *o = lv_obj_create(parent);
315	  if (!o) return NULL;
316	  lv_obj_remove_style_all(o);
317	  lv_obj_set_size(o, diam, diam);
318	  lv_obj_set_style_radius(o, LV_RADIUS_CIRCLE, 0);
319	  lv_obj_set_style_bg_color(o, lv_color_hex(color), 0);
320	  lv_obj_set_style_bg_opa(o, opa, 0);
321	  lv_obj_set_style_border_width(o, 0, 0);
322	  lv_obj_center(o);
323	  return o;
324	}
325	
326	int particle_flow_view_init(void)
327	{
328	  if (s_pf.initialized) return 0;
329	
330	  memset(&s_pf, 0, sizeof(s_pf));
331	  s_pf.state = PARTICLE_STATE_IDLE;
332	
333	  s_pf.screen = lv_obj_create(NULL);
334	  if (!s_pf.screen) return -ENOMEM;
335	  lv_obj_set_style_bg_color(s_pf.screen, lv_color_hex(0x1a1a2e), 0);
336	  lv_obj_set_style_bg_opa(s_pf.screen, LV_OPA_COVER, 0);
337	  lv_obj_set_style_text_font(s_pf.screen, &lv_font_misans_16_cjk, 0);
338	
339	  /* Display geometry: center + round bound. */
340	  lv_display_t *disp = lv_display_get_default();
341	  int32_t h = lv_display_get_horizontal_resolution(disp);
342	  int32_t v = lv_display_get_vertical_resolution(disp);
343	  s_pf.cx = h / 2;
344	  s_pf.cy = v / 2;
345	  int32_t half = (h < v ? h : v) / 2;
346	  s_pf.R = (half > 8) ? (half - 8) : 8;
347	  s_pf.R_sq = s_pf.R * s_pf.R;
348	
349	  /* Faint guide ring (shared motif with pet_status_view). */
350	  s_pf.guide_ring = lv_arc_create(s_pf.screen);
351	  if (s_pf.guide_ring)
352	    {
353	      lv_obj_set_size(s_pf.guide_ring, GUIDE_RING_DIAM, GUIDE_RING_DIAM);
354	      lv_obj_center(s_pf.guide_ring);
355	      lv_arc_set_bg_angles(s_pf.guide_ring, 0, 360);
356	      lv_arc_set_angles(s_pf.guide_ring, 0, 360);
357	      lv_obj_set_style_arc_width(s_pf.guide_ring, 2, 0);
358	      lv_obj_set_style_arc_width(s_pf.guide_ring, 2, LV_PART_MAIN);
359	      lv_obj_set_style_arc_color(s_pf.guide_ring, lv_color_hex(0x2a2a3e), LV_PART_MAIN);
360	      lv_obj_set_style_arc_color(s_pf.guide_ring, lv_color_hex(0x4ade80), 0);
361	      lv_obj_set_style_bg_opa(s_pf.guide_ring, LV_OPA_TRANSP, LV_PART_KNOB);
362	      lv_obj_remove_flag(s_pf.guide_ring, LV_OBJ_FLAG_CLICKABLE);
363	    }
364	
365	  /* Central pulsing core. */
366	  s_pf.core = make_circle(s_pf.screen, CORE_DIAM, 0x4ade80, LV_OPA_80);
367	
368	  /* Particles — scattered initially within the disc. */
369	  uint32_t seed = 0x1234abcd;
370	  for (int i = 0; i < N_PARTICLES; i++)
371	    {
372	      /* place around a ring with jitter so they don't overlap the core */
373	      int32_t ang = (i * 360 / N_PARTICLES) % 360;
374	      /* cheap sin/cos via a 4-bin triangle so no math.h: */
375	      int32_t qx = (ang < 90) ? ang : (ang < 270) ? (180 - ang) : (ang - 360);
376	      int32_t qy = ((ang + 270) % 360);
377	      qy = (qy < 90) ? qy : (qy < 270) ? (180 - qy) : (qy - 360);
378	      /* qx, qy ∈ [-90, 90] → normalize to [-1, 1] */
379	      int32_t rx = (qx * 0x7fff) / 90;
380	      int32_t ry = (qy * 0x7fff) / 90;
381	      int32_t radius = s_pf.R * 2 / 3;
382	      int32_t jitter = (lcg_next(&seed) * radius) / 16384;
383	      int32_t rr = radius + (jitter / 4);
384	      if (rr < 6) rr = 6;
385	      if (rr > s_pf.R - 2) rr = s_pf.R - 2;
386	
387	      s_pf.p[i].x = s_pf.cx + (int32_t)(((int64_t)rx * rr) / 0x7fff);
388	      s_pf.p[i].y = s_pf.cy + (int32_t)(((int64_t)ry * rr) / 0x7fff);
389	      s_pf.p[i].vx = lcg_next(&seed) / 8;   /* small initial velocity */
390	      s_pf.p[i].vy = lcg_next(&seed) / 8;
391	      s_pf.p[i].lcg = seed;
392	
393	      s_pf.particles[i] = make_circle(s_pf.screen, PARTICLE_DIAM,
394	                                       0x4ade80, LV_OPA_COVER);
395	      if (s_pf.particles[i])
396	        {
397	          int32_t prx = s_pf.p[i].x - (PARTICLE_DIAM / 2);
398	          int32_t pry = s_pf.p[i].y - (PARTICLE_DIAM / 2);
399	          lv_obj_set_pos(s_pf.particles[i], prx, pry);
400	          s_pf.p[i].last_rx = prx;
401	          s_pf.p[i].last_ry = pry;
402	        }
403	    }
404	
405	  /* State label. */
406	  s_pf.label = lv_label_create(s_pf.screen);
407	  if (s_pf.label)
408	    {
409	      lv_label_set_text(s_pf.label, s_state_text[PARTICLE_STATE_IDLE]);
410	      lv_obj_set_style_text_color(s_pf.label, lv_color_hex(0xcccccc), 0);
411	      lv_obj_set_style_text_font(s_pf.label, &lv_font_misans_16_cjk, 0);
412	      lv_obj_align(s_pf.label, LV_ALIGN_CENTER, 0, s_pf.cy / 2 + 8);
413	    }
414	
415	  /* Physics timer — runs on the LVGL thread, so widget mutation is safe. */
416	  s_pf.timer = lv_timer_create(timer_cb, TICK_MS, NULL);
417	  if (s_pf.timer)
418	    {
419	      lv_timer_set_repeat_count(s_pf.timer, -1);
420	    }
421	
422	  s_pf.initialized = true;
423	  syslog(LOG_INFO, "[%s] init OK (圆屏粒子流, %d 粒子, disp %dx%d R=%d)\n",
424	         TAG, N_PARTICLES, (int)h, (int)v, (int)s_pf.R);
425	  return 0;
426	}
