17	/**
18	 * ui_rpmsg_server.c — CP-side RPMsg receiver for the AP→CP UI channel (路 B).
19	 *
20	 * Lives on the CP core, which owns the round LCD + LVGL.  The CP app
21	 * (cp_ui_main) self-starts LVGL and the chat screen, then calls
22	 * ui_rpmsg_server_init() to open a dedicated RPMsg endpoint.  When the AP
23	 * agent (ui_rpmsg_client.c) sends a ui_rpmsg_msg, this server's rx callback
24	 * deserializes it and calls the REAL lvgl_ui_channel_* / lvgl_toast_* on
25	 * this core, where LVGL actually runs.
26	 *
27	 * TTS: lvgl_ui_channel_send() on CP internally calls voice_channel_speak(),
28	 * which is the cp_stubs.c no-op here — so the bubble renders on CP and audio
29	 * is handled separately by the AP shim.  No double audio.
30	 *
31	 * Mirrors the RPMsg endpoint pattern in
32	 * chips/bk7258/mb_ipc/bk_mailbox_rpmsg.c.  Flat build exposes the kernel
33	 * rpmsg symbols to this userspace builtin.
34	 *
35	 * Only compiled into CONFIG_EXAMPLES_AI_AGENT_UI_CP.
36	 */
37	
38	#include <nuttx/config.h>
39	
40	#ifdef CONFIG_EXAMPLES_AI_AGENT_UI_CP
41	
42	#include <stdbool.h>
43	#include <stdint.h>
44	#include <string.h>
45	#include <syslog.h>
46	
47	#include <nuttx/rpmsg/rpmsg.h>
48	
49	#include "ui/ui_rpmsg_proto.h"
50	#include "ui/lvgl_ui_channel.h"
51	#include "ui/lvgl_toast.h"
52	
53	#define TAG "ui_rpmsg_server"
54	
55	struct ui_rpmsg_server_state
56	{
57	  struct rpmsg_endpoint ept;
58	  bool registered;
59	  bool created;
60	};
61	
62	static struct ui_rpmsg_server_state g_ui_srv;
63	
64	/* On the CP the peer we care about is the AP core. */
65	#define UI_RPMSG_PEER_CPU "ap"
66	
67	/* ── dispatch a received message to the real LVGL functions ──────────── */
68	
69	static int ui_rpmsg_server_rx(struct rpmsg_endpoint *ept, void *data,
70	                               size_t len, uint32_t source, void *priv)
71	{
72	  const struct ui_rpmsg_msg *m = data;
73	  size_t need;
74	
75	  (void)ept;
76	  (void)source;
77	  (void)priv;
78	
79	  if (len < 4)  /* header = op + reserved + payload_len */
80	    {
81	      return -EINVAL;
82	    }
83	
84	  need = 4 + (size_t)m->payload_len;
85	  if (len < need)
86	    {
87	      syslog(LOG_WARNING, "[%s] short msg op=%u len=%zu need=%zu\n",
88	             TAG, m->op, len, need);
89	      return -EINVAL;
90	    }
91	
92	  switch (m->op)
93	    {
94	      case UI_RPMSG_INIT:
95	        (void)lvgl_ui_channel_init();
96	        break;
97	
98	      case UI_RPMSG_START:
99	        (void)lvgl_ui_channel_start();
100	        break;
101	
102	      case UI_RPMSG_STOP:
103	        lvgl_ui_channel_stop();
104	        break;
105	
106	      case UI_RPMSG_SHOW:
107	        lvgl_ui_channel_show();
108	        break;
109	
110	      case UI_RPMSG_SEND:
111	        {
112	          /* Wire text is len-prefixed, not NUL-terminated. */
113	          char text[UI_RPMSG_MAX_TEXT + 1];
114	          size_t tl = m->payload_len;
115	          if (tl > UI_RPMSG_MAX_TEXT)
116	            {
117	              tl = UI_RPMSG_MAX_TEXT;
118	            }
119	          memcpy(text, m->payload, tl);
120	          text[tl] = '\0';
121	          /* Real CP send(): builds the bubble + voice_channel_speak()
122	             (no-op stub here).  Audio is handled on the AP side. */
123	          (void)lvgl_ui_channel_send(text);
124	        }
125	        break;
126	
127	      case UI_RPMSG_SEND_EX:
128	        {
129	          /* payload = [bar_color:u32le][text..] (text not NUL-terminated). */
130	          if (m->payload_len < sizeof(uint32_t))
131	            {
132	              break;
133	            }
134	          uint32_t bar_color;
135	          memcpy(&bar_color, m->payload, sizeof(uint32_t));
136	          size_t tl = m->payload_len - sizeof(uint32_t);
137	          char text[UI_RPMSG_MAX_TEXT + 1];
138	          if (tl > UI_RPMSG_MAX_TEXT)
139	            {
140	              tl = UI_RPMSG_MAX_TEXT;
141	            }
142	          memcpy(text, m->payload + sizeof(uint32_t), tl);
143	          text[tl] = '\0';
144	          (void)lvgl_ui_channel_send_ex(text, bar_color);
145	        }
146	        break;
147	
148	      case UI_RPMSG_SET_PTT:
149	        {
150	          if (m->payload_len < 1)
151	            {
152	              break;
153	            }
154	          (void)lvgl_ui_channel_set_ptt((int)m->payload[0]);
155	        }
156	        break;
157	
158	      case UI_RPMSG_SEND_USER:
159	        {
160	          /* Echo the recognized user utterance as a right-aligned bubble. */
161	          char text[UI_RPMSG_MAX_TEXT + 1];
162	          size_t tl = m->payload_len;
163	          if (tl > UI_RPMSG_MAX_TEXT)
164	            {
165	              tl = UI_RPMSG_MAX_TEXT;
166	            }
167	          memcpy(text, m->payload, tl);
168	          text[tl] = '\0';
169	          (void)lvgl_ui_channel_send_user(text);
170	        }
171	        break;
172	
173	      case UI_RPMSG_SET_PET_STATE:
174	        {
175	          /* Drive the pet status ring home screen (M7 差异化页) from the AP
176	           * agent's lifecycle state.  No-op if PET_STATUS is off. */
177	          if (m->payload_len < 1)
178	            {
179	              break;
180	            }
181	          (void)lvgl_ui_channel_set_pet_state((int)m->payload[0]);
182	        }
183	        break;
184	
185	      case UI_RPMSG_SET_PAGE:
186	        {
187	          /* Switch the round-screen page (0=pet home, 1=particle flow).
188	           * Delegates to the CP-side lvgl_ui_channel_set_page, which gates
189	           * each page behind its CONFIG guard. */
190	          if (m->payload_len < 1)
191	            {
192	              break;
193	            }
194	          (void)lvgl_ui_channel_set_page((int)m->payload[0]);
195	        }
196	        break;
197	
198	      case UI_RPMSG_TOAST:
199	        {
200	          if (m->payload_len < 2 * sizeof(uint32_t))
201	            {
202	              break;
203	            }
204	          uint32_t bar_color;
205	          uint32_t duration_ms;
206	          memcpy(&bar_color,  m->payload + 0, sizeof(uint32_t));
207	          memcpy(&duration_ms, m->payload + 4, sizeof(uint32_t));
208	
209	          const char *title = (const char *)(m->payload + 8);
210	          size_t avail = m->payload_len - 8;
211	          /* title is NUL-terminated within the wire payload. */
212	          size_t tlen = strnlen(title, avail);
213	          const char *body = "";
214	          if (tlen < avail)
215	            {
216	              body = title + tlen + 1;  /* skip the NUL after title */
217	            }
218	          lvgl_toast_show_async(title, body, bar_color, duration_ms);
219	        }
220	        break;
221	
222	      default:
223	        syslog(LOG_WARNING, "[%s] unknown op %u\n", TAG, m->op);
224	        break;
225	    }
226	
227	  return 0;
228	}
