217	  memset(&m, 0, sizeof(m));
218	  m.op = UI_RPMSG_SEND;
219	  tlen = strlen(text);
220	  if (tlen > UI_RPMSG_MAX_TEXT)
221	    {
222	      tlen = UI_RPMSG_MAX_TEXT;
223	    }
224	  m.payload_len = (uint16_t)tlen;
225	  memcpy(m.payload, text, tlen);
226	
227	  ret = ui_rpmsg_send(&m);
228	  if (ret < 0)
229	    {
230	      syslog(LOG_WARNING, "[%s] send bubble to CP failed: %d\n", TAG, ret);
231	    }
232	  return ret;
