372	void lvgl_toast_show_async(const char *title, const char *body,
373	                           uint32_t bar_color, uint32_t duration_ms)
374	{
375	  struct ui_rpmsg_msg m;
376	  size_t off, tlen, blen;
377	
378	  memset(&m, 0, sizeof(m));
379	  m.op = UI_RPMSG_TOAST;
380	
381	  /* payload layout: [bar_color:u32le][duration_ms:u32le][title\0body\0] */
382	  uint32_t *hdr = (uint32_t *)m.payload;
383	  hdr[0] = bar_color;
384	  hdr[1] = duration_ms;
385	  off = 2 * sizeof(uint32_t);
386	
387	  tlen = (title != NULL) ? strlen(title) + 1 : 0;
388	  blen = (body  != NULL) ? strlen(body)  + 1 : 0;
389	
390	  if (off + tlen + blen > UI_RPMSG_MAX_PAYLOAD)
391	    {
392	      /* Truncate body first, then title, keeping both NUL-terminated. */
393	      size_t room = UI_RPMSG_MAX_PAYLOAD - off;
394	      if (tlen > room)
395	        {
396	          tlen = room;
397	          blen = 0;
398	        }
399	      else if (tlen + blen > room)
400	        {
401	          blen = room - tlen;
402	        }
403	      /* Ensure a NUL terminator even when truncated. */
404	      if (tlen > 0)
405	        {
406	          m.payload[off + tlen - 1] = '\0';
407	        }
408	      if (blen > 0)
409	        {
410	          m.payload[off + tlen + blen - 1] = '\0';
411	        }
412	    }
413	
414	  if (tlen > 0)
415	    {
416	      memcpy(m.payload + off, title, tlen);
417	    }
418	  if (blen > 0)
419	    {
420	      memcpy(m.payload + off + tlen, body, blen);
421	    }
422	  m.payload_len = (uint16_t)(off + tlen + blen);
423	
424	  (void)ui_rpmsg_send(&m);
425	}
