140	static void stop_anim(void)
141	{
142	  /* Delete any anim bound to our widgets. lv_anim_delete is a no-op if none. */
143	  if (s_pet.ring)  lv_anim_delete(s_pet.ring,  spin_cb);
144	  if (s_pet.face)  lv_anim_delete(s_pet.face,  breathe_cb);
145	  if (s_pet.face)  lv_anim_delete(s_pet.face,  shake_cb);
146	  if (s_pet.eye_l) lv_anim_delete(s_pet.eye_l, blink_cb);
147	  if (s_pet.eye_r) lv_anim_delete(s_pet.eye_r, blink_cb);
148	  s_pet.anim_active = false;
149	}
