151	/* Position pupils within eyes according to state. */
152	static void apply_pupils(enum pet_state st)
153	{
154	  int dx = 0, dy = 0;            /* pupil offset from eye center */
155	  lv_opa_t eye_opa = LV_OPA_COVER;
156	  switch (st)
157	    {
158	      case PET_STATE_THINKING:  dy = -3; break;             /* look up */
159	      case PET_STATE_LISTENING: dy = 3;  break;              /* look down */
160	      case PET_STATE_EXECUTING: dx = 0;  dy = 0; break;      /* focused */
161	      case PET_STATE_WAITING:   /* blink handled by anim; pupils normal */
162	      case PET_STATE_IDLE:      dx = 0;  dy = 0; break;
163	      case PET_STATE_ERROR:     dx = 3;  dy = -3; eye_opa = LV_OPA_60; break;
164	      default: break;
165	    }
166	  if (s_pet.pupil_l) lv_obj_align(s_pet.pupil_l, LV_ALIGN_CENTER, -dx, dy);
167	  if (s_pet.pupil_r) lv_obj_align(s_pet.pupil_r, LV_ALIGN_CENTER,  dx, dy);
168	  /* For ERROR, dim eyes a touch so the "X" feel reads (pupils at corners). */
169	  if (s_pet.eye_l) lv_obj_set_style_opa(s_pet.eye_l, eye_opa, 0);
170	  if (s_pet.eye_r) lv_obj_set_style_opa(s_pet.eye_r, eye_opa, 0);
171	}
