173	static void start_anim_for(enum pet_state st)
174	{
175	  lv_anim_t a;
176	  uint32_t color = s_state_color[st];
177	
178	  stop_anim();
179	  if (!s_pet.ring || !s_pet.face) return;
180	
181	  /* Ring color always tracks state; base angles reset per effect. */
182	  lv_obj_set_style_arc_color(s_pet.ring, lv_color_hex(color), 0);
183	
184	  switch (st)
185	    {
186	      case PET_STATE_THINKING:
187	      case PET_STATE_LISTENING:
188	        lv_anim_init(&a);
189	        lv_anim_set_var(&a, s_pet.ring);
190	        lv_anim_set_values(&a, 0, 360);
191	        lv_anim_set_time(&a, 1400);
192	        lv_anim_set_exec_cb(&a, spin_cb);
193	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
194	        lv_anim_start(&a);
195	        break;
196	      case PET_STATE_EXECUTING:
197	        lv_anim_init(&a);
198	        lv_anim_set_var(&a, s_pet.ring);
199	        lv_anim_set_values(&a, 0, 360);
200	        lv_anim_set_time(&a, 900);
201	        lv_anim_set_exec_cb(&a, fill_cb);
202	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
203	        lv_anim_start(&a);
204	        break;
205	      case PET_STATE_IDLE:
206	        lv_anim_init(&a);
207	        lv_anim_set_var(&a, s_pet.face);
208	        lv_anim_set_values(&a, 0, 100);
209	        lv_anim_set_time(&a, 1800);
210	        lv_anim_set_exec_cb(&a, breathe_cb);
211	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
212	        lv_anim_start(&a);
213	        lv_arc_set_angles(s_pet.ring, 0, 360);  /* full ring */
214	        break;
215	      case PET_STATE_WAITING:
216	        lv_anim_init(&a);
217	        lv_anim_set_var(&a, s_pet.eye_l);
218	        lv_anim_set_values(&a, 0, 100);
219	        lv_anim_set_time(&a, 700);
220	        lv_anim_set_exec_cb(&a, blink_cb);
221	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
222	        lv_anim_start(&a);
223	        lv_anim_init(&a);
224	        lv_anim_set_var(&a, s_pet.eye_r);
225	        lv_anim_set_values(&a, 0, 100);
226	        lv_anim_set_time(&a, 700);
227	        lv_anim_set_exec_cb(&a, blink_cb);
228	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
229	        lv_anim_start(&a);
230	        lv_arc_set_angles(s_pet.ring, 0, 360);
231	        break;
232	      case PET_STATE_ERROR:
233	        lv_anim_init(&a);
234	        lv_anim_set_var(&a, s_pet.face);
235	        lv_anim_set_values(&a, 0, 100);
236	        lv_anim_set_time(&a, 350);
237	        lv_anim_set_exec_cb(&a, shake_cb);
238	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
239	        lv_anim_start(&a);
240	        lv_arc_set_angles(s_pet.ring, 0, 360);
241	        break;
242	      default:
243	        lv_arc_set_angles(s_pet.ring, 0, 360);
244	        break;
245	    }
246	  s_pet.anim_active = true;
247	}
