65	/* Per-state physics knobs:
66	 *   perturb  — LCG noise amplitude fed into velocity (q8 units)
67	 *   swirl    — tangential bias strength (rotation; +CW, -CCW)
68	 *   radial   — radial bias (+outward / -inward)
69	 *   damp     — velocity retention per tick (0..256) */
70	typedef struct {
71	  int32_t perturb;
72	  int32_t swirl;
73	  int32_t radial;
74	  int32_t damp;
75	} phys_t;
76	
77	static const phys_t s_phys[] = {
78	  [PARTICLE_STATE_IDLE]      = { 10,   4,   0, 248 },  /* gentle drift */
79	  [PARTICLE_STATE_LISTENING] = { 16,  10, -18, 244 },  /* inward + slow swirl */
80	  [PARTICLE_STATE_THINKING] = { 20,  34,   0, 250 },  /* fast swirl */
81	  [PARTICLE_STATE_EXECUTING] = { 28,  -8,  26, 246 }, /* outward burst */
82	  [PARTICLE_STATE_WAITING]   = {  4,   2,   0, 220 },  /* near-frozen pulse */
83	  [PARTICLE_STATE_ERROR]     = { 90,   0,   0, 252 },  /* chaotic scatter */
84	};
85	
86	struct particle_s {
87	  int32_t x, y;          /* position, pixels */
88	  int32_t vx, vy;        /* velocity, q8 (256 = 1px/tick) */
89	  uint32_t lcg;          /* per-particle pseudo-noise state */
90	  int32_t last_rx, last_ry;  /* last rendered top-left; skip set_pos if unchanged */
91	};
92	
93	struct pf_state_s {
94	  bool initialized;
95	  bool visible;
96	  enum particle_state state;
97	  lv_obj_t *screen;
98	  lv_obj_t *guide_ring;  /* faint lv_arc, shared motif with pet */
99	  lv_obj_t *core;        /* central pulsing circle */
100	  lv_obj_t *particles[N_PARTICLES];
101	  lv_obj_t *label;
102	  lv_obj_t *prev_screen;
103	  struct particle_s p[N_PARTICLES];
104	  lv_timer_t *timer;
105	  uint32_t tick;
106	  /* display geometry (pixels) */
107	  int32_t cx, cy, R, R_sq;
108	};
