211	/* ── Ring buffer ──────────────────────────────────────────────── */
212	
213	/**
214	 * Copy text into a fixed buffer with UTF-8-aware truncation.  Copies at most
215	 * dst_size-1 bytes, then if the cut lands inside a multi-byte UTF-8 sequence
216	 * (leading byte 0xC0..0xF4 not followed by enough continuation bytes 0x80..0xBF),
217	 * trims back to the last complete character.  Always NUL-terminates.
218	 *
219	 * This prevents a half-cut Chinese char from rendering as a replacement glyph
220	 * at the end of a truncated Agent reply.
221	 */
222	static void chat_view_copy_text(char* dst, const char* src, size_t dst_size)
223	{
224	    if (dst_size == 0) return;
225	    size_t n = strnlen(src, dst_size - 1);
226	    memcpy(dst, src, n);
227	    dst[n] = '\0';
228	
229	    /* If we filled the buffer, the last char may be incomplete.  Walk back
230	     * from the end to find a UTF-8 leading byte and check its expected length
231	     * against the remaining bytes. */
232	    if (n < dst_size - 1) return;          /* src fit fully, no truncation */
233	    size_t i = n;
234	    while (i > 0) {
235	        unsigned char c = (unsigned char)dst[i - 1];
236	        if ((c & 0xC0) != 0x80) break;     /* not a continuation byte */
237	        i--;
238	    }
239	    if (i == 0) return;                     /* all continuation bytes? give up */
240	    unsigned char lead = (unsigned char)dst[i - 1];
241	    size_t need;
242	    if      ((lead & 0x80) == 0x00) need = 1;   /* ASCII */
243	    else if ((lead & 0xE0) == 0xC0) need = 2;
244	    else if ((lead & 0xF0) == 0xE0) need = 3;
245	    else if ((lead & 0xF8) == 0xF0) need = 4;
246	    else { dst[i - 1] = '\0'; return; }         /* invalid lead, cut it */
247	    if (n - (i - 1) < need) {
248	        dst[i - 1] = '\0';                      /* incomplete seq, trim it */
249	    }
250	}
251	
252	/**
253	 * Add a message to the chat history ring buffer.
254	 *
255	 * When count < CHAT_HISTORY_MAX, writes at head and increments count.
256	 * When count == CHAT_HISTORY_MAX, overwrites the oldest message and
257	 * deletes its LVGL bubble widget if present.
258	 *
259	 * Text is truncated to LVGL_UI_MSG_MAX_LEN - 1 bytes with explicit
260	 * NUL termination (rule coding-9), UTF-8-aware so a multi-byte char is
261	 * never split in half.
262	 *
263	 * Returns pointer to the newly written slot (inside the ring buffer,
264	 * no stack allocation of chat_msg_t — rule coding-6).
265	 */
266	static chat_msg_t* chat_history_add(chat_history_t* h, const char* text, bool is_user)
267	{
268	    chat_msg_t* slot = &h->msgs[h->head];
269	
270	    /* When buffer is full, recycle the oldest slot */
271	    if (h->count == CHAT_HISTORY_MAX) {
272	        if (slot->bubble) {
273	            lv_obj_del(slot->bubble);
274	            slot->bubble = NULL;
275	        }
276	    } else {
277	        h->count++;
278	    }
279	
280	    /* Write message text with UTF-8-aware truncation */
281	    chat_view_copy_text(slot->text, text, LVGL_UI_MSG_MAX_LEN);
282	
283	    slot->is_user = is_user;
284	    slot->bubble = NULL;
285	
286	    h->head = (h->head + 1) % CHAT_HISTORY_MAX;
287	
288	    return slot;
289	}
