373	int lvgl_ui_channel_init(void)
374	{
375	    int chat_h;
376	    int ret = 0;
377	    /* Display geometry — queried from the active display so the layout
378	     * adapts to both the 466×466 round watch (real hardware) and the
379	     * 1280×800 rectangle (qemu). Falls back to the 466 constants when
380	     * no display is registered yet. */
381	    lv_coord_t disp_w = LVGL_UI_SCREEN_W;
382	    lv_coord_t disp_h = LVGL_UI_SCREEN_H;
383	
384	    /* Idempotent: already initialized */
385	    if (s_state.initialized) {
386	        return 0;
387	    }
388	
389	    syslog(LOG_INFO, "[%s] init\n", TAG);
390	
391	    /* If LVGL is not yet initialized (qemu: no miwear/launcher owns it),
392	     * bring it up ourselves: lv_init + lv_nuttx_init(/dev/fb0) + a
393	     * lv_timer_handler loop thread.  On real hardware where miwear already
394	     * did this, lv_is_initialized() is true and we skip — only creating
395	     * widgets on the existing display, as before. */
396	    if (!lv_is_initialized()) {
397	        lv_nuttx_dsc_t dsc;
398	
399	        syslog(LOG_INFO, "[%s] LVGL not initialized; self-init on /dev/fb0\n", TAG);
400	
401	        lv_init();
402	        lv_nuttx_dsc_init(&dsc);
403	        /* fb_path defaults to /dev/fb0 in lv_nuttx_dsc_init; GOLDFISH_GPU_FB
404	         * provides it on qemu-arm64-v8a-ap. */
405	        lv_nuttx_init(&dsc, &s_lv_result);
406	
407	        if (s_lv_result.disp == NULL) {
408	            syslog(LOG_ERR, "[%s] lv_nuttx_init failed (no display)\n", TAG);
409	            ret = -EIO;
410	            goto cleanup;
411	        }
412	
413	        /* Start the LVGL event loop thread (miwear would own this on real
414	         * hardware; on qemu we run it ourselves). */
415	        s_lv_loop_running = true;
416	        /* LVGL rendering + CJK (SIMSUN/FreeType) glyph rasterization needs a
417	         * deep stack; the default pthread stack overflows -> recursive
418	         * assert. Use an explicitly sized stack. */
419	        pthread_attr_t lv_attr;
420	        pthread_attr_init(&lv_attr);
421	        pthread_attr_setstacksize(&lv_attr, AGENT_LVGL_UI_STACK);
422	        if (pthread_create(&s_lv_loop_tid, &lv_attr, lv_loop_thread, NULL) != 0) {
423	            syslog(LOG_ERR, "[%s] LVGL loop thread create failed\n", TAG);
424	            lv_nuttx_deinit(&s_lv_result);
425	            s_lv_loop_running = false;
426	            ret = -EIO;
427	            goto cleanup;
428	        }
429	        s_lv_owned = true;
430	        syslog(LOG_INFO, "[%s] LVGL self-init OK, loop thread started\n", TAG);
431	    } else {
432	        syslog(LOG_INFO, "[%s] LVGL already initialized (system owns it)\n", TAG);
433	    }
434	
435	    /* Query the real display resolution so the layout adapts to the
436	     * actual screen (466 round watch on hardware, 1280×800 on qemu)
437	     * instead of always using the 466 constants. */
438	    lv_display_t* disp = lv_display_get_default();
439	    if (disp) {
440	        lv_coord_t rw = lv_display_get_horizontal_resolution(disp);
441	        lv_coord_t rh = lv_display_get_vertical_resolution(disp);
442	        if (rw > 0 && rh > 0) {
443	            disp_w = rw;
444	            disp_h = rh;
445	            syslog(LOG_INFO, "[%s] display %dx%d\n", TAG, disp_w, disp_h);
446	        }
447	    }
448	
449	    /* Create main screen with dark background */
450	    s_state.screen = lv_obj_create(NULL);
451	    if (!s_state.screen) {
452	        syslog(LOG_ERR, "[%s] screen create failed\n", TAG);
453	        ret = -EIO;
454	        goto cleanup;
455	    }
456	
457	    lv_obj_set_style_bg_color(s_state.screen, lv_color_hex(UI_PAL_BG), 0);
458	    lv_obj_set_style_bg_opa(s_state.screen, LV_OPA_COVER, 0);
459	    /* Do NOT call lv_screen_load() here — we load the screen on
460	     * demand when the user activates the chat UI, to avoid
461	     * hijacking the system's current screen at boot. */
462	
463	    /* Default text font: the app-owned statically-compiled MiSans-16 CJK font
464	     * (3755 GB2312-1 common chars + ASCII + fullwidth punctuation, baked into
465	     * the binary via lv_font_conv — zero runtime malloc/rasterization) so
466	     * Agent reply Chinese text renders on qemu with full coverage and cannot
467	     * corrupt the heap.  Falls back to SimSun-16 (1000 chars) then Montserrat. */
468	    lv_obj_set_style_text_font(s_state.screen, &lv_font_misans_16_cjk, 0);
469	
470	    /* Step 5: Create Chat View container */
471	    chat_h = disp_h - LVGL_UI_PADDING_TOP - LVGL_UI_PADDING_BOTTOM
472	        - LVGL_UI_PTT_SIZE - 20;
473	
474	    s_state.chat_list = lv_obj_create(s_state.screen);
475	    if (!s_state.chat_list) {
476	        syslog(LOG_ERR, "[%s] chat_list create failed\n", TAG);
477	        ret = -EIO;
478	        goto cleanup;
479	    }
480	
481	    lv_obj_set_size(s_state.chat_list,
482	        disp_w - 2 * LVGL_UI_PADDING_H, chat_h);
483	    lv_obj_align(s_state.chat_list, LV_ALIGN_TOP_MID, 0, LVGL_UI_PADDING_TOP);
484	    lv_obj_set_scroll_dir(s_state.chat_list, LV_DIR_VER);
485	    lv_obj_set_flex_flow(s_state.chat_list, LV_FLEX_FLOW_COLUMN);
486	    lv_obj_set_style_pad_row(s_state.chat_list, LVGL_UI_CHAT_GAP, 0);
487	    lv_obj_set_style_bg_opa(s_state.chat_list, LV_OPA_TRANSP, 0);
488	    lv_obj_set_style_border_width(s_state.chat_list, 0, 0);
489	    lv_obj_set_style_pad_left(s_state.chat_list, 4, 0);
490	    lv_obj_set_style_pad_right(s_state.chat_list, 4, 0);
491	    lv_obj_set_style_pad_top(s_state.chat_list, 4, 0);
492	    lv_obj_set_style_pad_bottom(s_state.chat_list, 4, 0);
493	    lv_obj_set_scrollbar_mode(s_state.chat_list, LV_SCROLLBAR_MODE_OFF);
494	    lv_obj_add_flag(s_state.chat_list, LV_OBJ_FLAG_SCROLL_MOMENTUM);
495	
496	    /* Step 6: Create PTT Button */
497	    s_state.ptt_btn = lv_btn_create(s_state.screen);
498	    if (!s_state.ptt_btn) {
499	        syslog(LOG_ERR, "[%s] ptt_btn create failed\n", TAG);
500	        ret = -EIO;
501	        goto cleanup;
502	    }
503	
504	    lv_obj_set_size(s_state.ptt_btn, LVGL_UI_PTT_SIZE, LVGL_UI_PTT_SIZE);
505	    lv_obj_align(s_state.ptt_btn, LV_ALIGN_BOTTOM_MID, 0, -LVGL_UI_PADDING_BOTTOM);
506	    lv_obj_set_style_radius(s_state.ptt_btn, LVGL_UI_PTT_SIZE / 2, 0);
507	    lv_obj_set_style_bg_color(s_state.ptt_btn, lv_color_hex(UI_PAL_ACCENT), 0);
508	    lv_obj_set_style_shadow_width(s_state.ptt_btn, 12, 0);
509	    lv_obj_set_style_shadow_color(s_state.ptt_btn, lv_color_hex(UI_PAL_ACCENT), 0);
510	    lv_obj_set_style_shadow_opa(s_state.ptt_btn, LV_OPA_40, 0);
511	
512	    s_state.ptt_label = lv_label_create(s_state.ptt_btn);
513	    if (!s_state.ptt_label) {
514	        syslog(LOG_ERR, "[%s] ptt_label create failed\n", TAG);
515	        ret = -EIO;
516	        goto cleanup;
517	    }
518	
519	    /* Use Unicode microphone emoji — MiSans includes it, unlike
520	     * LV_SYMBOL_AUDIO which needs FontAwesome glyphs not in MiSans
521	     * and renders as a rectangle. */
522	    lv_label_set_text(s_state.ptt_label, PTT_ICON_MIC);
523	    lv_obj_center(s_state.ptt_label);
524	
525	    lv_obj_add_event_cb(s_state.ptt_btn, ptt_btn_event_cb, LV_EVENT_ALL, NULL);
526	
527	    /* Step 7: Create Recording Indicator (initially hidden) */
528	    s_state.rec_indicator = lv_label_create(s_state.screen);
529	    if (!s_state.rec_indicator) {
530	        syslog(LOG_ERR, "[%s] rec_indicator create failed\n", TAG);
531	        ret = -EIO;
532	        goto cleanup;
533	    }
534	
535	    lv_label_set_text(s_state.rec_indicator, "");
536	    lv_obj_align_to(s_state.rec_indicator, s_state.ptt_btn, LV_ALIGN_OUT_TOP_MID, 0, -8);
537	    lv_obj_add_flag(s_state.rec_indicator, LV_OBJ_FLAG_HIDDEN);
538	
539	    /* Step 7b: Create Close Button (top-right corner) */
540	    s_state.close_btn = lv_btn_create(s_state.screen);
541	    if (!s_state.close_btn) {
542	        syslog(LOG_ERR, "[%s] close_btn create failed\n", TAG);
543	        ret = -EIO;
544	        goto cleanup;
545	    }
