547	    lv_obj_set_size(s_state.close_btn, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
548	    /* Position close button inside the visible circular area.
549	     * On a 466x466 round screen (radius 233), the top-right corner
550	     * is clipped by the bezel.  Place the button at a position that
551	     * is safely inside the circle: top-center with a rightward offset.
552	     * At y=30 from top, the visible horizontal range is roughly
553	     * center ± sqrt(233²-203²) ≈ ±115px, so x offset of +80 is safe. */
554	    lv_obj_align(s_state.close_btn, LV_ALIGN_TOP_MID, 80, LVGL_UI_PADDING_TOP - 30);
555	    lv_obj_set_style_bg_opa(s_state.close_btn, LV_OPA_TRANSP, 0);
556	    lv_obj_set_style_border_width(s_state.close_btn, 0, 0);
557	    lv_obj_set_style_shadow_opa(s_state.close_btn, LV_OPA_TRANSP, 0);
558	    lv_obj_set_style_pad_all(s_state.close_btn, 8, 0);
559	
560	    lv_obj_t* close_label = lv_label_create(s_state.close_btn);
561	    if (close_label) {
562	        lv_label_set_text(close_label, CLOSE_BTN_TEXT);
563	        lv_obj_set_style_text_color(close_label, lv_color_hex(0x999999), 0);
564	        lv_obj_center(close_label);
565	    }
566	
567	    lv_obj_add_event_cb(s_state.close_btn, close_btn_event_cb, LV_EVENT_CLICKED, NULL);
568	
569	    /* Step 8: Initialize chat history and mutex */
570	    memset(&s_state.history, 0, sizeof(chat_history_t));
571	    pthread_mutex_init(&s_state.lock, NULL);
572	
573	    s_state.initialized = true;
574	    syslog(LOG_INFO, "[%s] init OK\n", TAG);
575	
576	#ifdef CONFIG_AI_AGENT_PET_STATUS
577	    /* Build the pet status ring home screen (M7 差异化页).  It is NOT loaded
578	     * here — cp_ui_main (or the AP via RPMsg) decides when to show it.  The
579	     * idle-yield timer runs in the LVGL thread and only fires when the chat
580	     * screen owns the foreground. */
581	    (void)pet_status_view_init();
582	    /* Surface the pet as the boot/home screen immediately.  On CP this is
583	     * idempotent with cp_ui_main's explicit show(); on qemu (no cp_ui_main,
584	     * no AP→CP RPMsg) it is the only thing that brings the pet up at boot. */
585	    pet_status_view_show();
586	    s_pet_idle_timer = lv_timer_create(pet_idle_timer_cb, 1000, NULL);
587	    if (s_pet_idle_timer)
588	      {
589	        lv_timer_set_repeat_count(s_pet_idle_timer, -1);
590	      }
591	    pet_idle_reset();
592	#endif
593	#ifdef CONFIG_AI_AGENT_PARTICLE_FLOW
594	    /* M7 差异化页 ②: build the particle flow screen (NOT loaded — the pet is
595	     * the cold-start home screen; the particle page is reached via set_page 1).
596	     * Init here so it is ready to show without a per-call create latency. */
597	    (void)particle_flow_view_init();
598	#endif
599	#if defined(CONFIG_AI_AGENT_PET_STATUS) && defined(CONFIG_AI_AGENT_PARTICLE_FLOW)
600	    /* Idle auto-rotate between pet ① and particle ② (UI方案.md §2.4).
601	     * 1 s period polls the idle condition; the cb self-throttles to
602	     * ROTATE_INTERVAL_MS between actual switches. */
603	    s_rotate_timer = lv_timer_create(rotate_timer_cb, 1000, NULL);
604	    if (s_rotate_timer)
605	      {
606	        lv_timer_set_repeat_count(s_rotate_timer, -1);
607	      }
608	    rotate_idle_reset();
609	#endif
610	    return 0;
611	
612	cleanup:
613	    /* Release resources in reverse order (coding-2) */
614	
615	    if (s_state.screen) {
616	        lv_obj_del(s_state.screen);
617	        s_state.screen = NULL;
618	        /* Child widgets are deleted with the screen */
619	        s_state.chat_list = NULL;
620	        s_state.ptt_btn = NULL;
621	        s_state.ptt_label = NULL;
622	        s_state.rec_indicator = NULL;
623	        s_state.close_btn = NULL;
624	    }
625	
626	    syslog(LOG_ERR, "[%s] init failed (rc=%d)\n", TAG, ret);
627	    return ret;
628	}
