653	/* Semaphore for synchronizing async stop with LVGL thread */
654	static sem_t s_stop_sem;
655	
656	/* Internal cleanup — must be called from LVGL thread context */
657	static void lvgl_ui_do_cleanup(void)
658	{
659	    int i;
660	
661	    if (s_state.screen) {
662	        /* If our screen is the active screen, restore the previous
663	         * (launcher) screen first.  Deleting the active screen without
664	         * loading another one leaves LVGL with no valid screen — the
665	         * next lv_timer_handler() call crashes with a MemManage fault
666	         * (NULL pointer dereference at offset 0x32 in lv_obj_t). */
667	        if (s_state.screen_visible && s_state.prev_screen) {
668	            lv_screen_load(s_state.prev_screen);
669	        }
670	
671	        lv_obj_del(s_state.screen);
672	        s_state.screen = NULL;
673	    }
674	
675	    s_state.screen_visible = false;
676	    s_state.prev_screen = NULL;
677	
678	    s_state.chat_list = NULL;
679	    s_state.ptt_btn = NULL;
680	    s_state.ptt_label = NULL;
681	    s_state.rec_indicator = NULL;
682	    s_state.close_btn = NULL;
683	
684	    for (i = 0; i < CHAT_HISTORY_MAX; i++) {
685	        s_state.history.msgs[i].bubble = NULL;
686	    }
687	
688	    s_state.history.head = 0;
689	    s_state.history.count = 0;
690	
691	    /* Note: when we self-initialized LVGL (s_lv_owned, qemu case), the
692	     * lv_timer_handler loop thread is intentionally left running — it is
693	     * torn down only when the ai_agent process exits.  Stopping it from
694	     * within cleanup (which itself runs in that loop thread via
695	     * lv_async_call) would self-deadlock.  Widget deletion above is safe
696	     * because the loop is still alive to process it. */
697	}
698	
699	static void stop_screen_async_cb(void* data)
700	{
701	    (void)data;
702	
703	    lvgl_ui_do_cleanup();
704	    sem_post(&s_stop_sem);
705	}
706	
707	/* Stop from within the LVGL thread (e.g. close button callback).
708	 * Performs cleanup directly — no async scheduling needed. */
709	void lvgl_ui_channel_stop_sync(void)
710	{
711	    if (!s_state.initialized || !s_state.running) {
712	        return;
713	    }
714	
715	    syslog(LOG_INFO, "[%s] stopping (sync)\n", TAG);
716	
717	    s_state.running = false;
718	    lvgl_ui_do_cleanup();
719	    pthread_mutex_destroy(&s_state.lock);
720	    s_state.initialized = false;
721	
722	    syslog(LOG_INFO, "[%s] stopped\n", TAG);
723	}
724	
725	/* Stop from an external thread (e.g. velaquit shutdown).
726	 * Schedules cleanup in the LVGL thread to avoid racing with the
727	 * miwear/launcher event loop. */
728	void lvgl_ui_channel_stop(void)
729	{
730	    /* No-op if not initialized or not running */
731	    if (!s_state.initialized || !s_state.running) {
732	        return;
733	    }
734	
735	    syslog(LOG_INFO, "[%s] stopping\n", TAG);
736	
737	    /* Mark as not running first — prevents callbacks (PTT, close_btn,
738	     * chat_view_add_message) from touching widgets during teardown. */
739	    s_state.running = false;
740	
741	    /* Schedule cleanup in the LVGL thread to avoid racing with the
742	     * miwear/launcher event loop.  Direct lv_obj_del from the
743	     * shutdown thread causes a MemManage fault because the LVGL
744	     * thread may be mid-render on the same objects. */
745	    sem_init(&s_stop_sem, 0, 0);
746	    lv_async_call(stop_screen_async_cb, NULL);
747	
748	    /* Wait for LVGL thread to complete the deletion (timeout 2s) */
749	    struct timespec ts;
750	
751	    clock_gettime(CLOCK_REALTIME, &ts);
752	    ts.tv_sec += 2;
753	
754	    if (sem_timedwait(&s_stop_sem, &ts) != 0) {
755	        syslog(LOG_WARNING,
756	            "[%s] async stop timed out, forcing cleanup\n", TAG);
757	        /* Fallback: NULL out pointers without deleting (leak is
758	         * acceptable during shutdown to avoid crash). */
759	        s_state.screen = NULL;
760	        s_state.chat_list = NULL;
761	        s_state.ptt_btn = NULL;
762	        s_state.ptt_label = NULL;
763	        s_state.rec_indicator = NULL;
764	        s_state.close_btn = NULL;
765	    }
766	
767	    sem_destroy(&s_stop_sem);
768	
769	    /* Destroy the mutex */
770	    pthread_mutex_destroy(&s_state.lock);
771	
772	    s_state.initialized = false;
773	
774	    syslog(LOG_INFO, "[%s] stopped\n", TAG);
775	}
