777	/* Async callback: load screen inside LVGL thread context */
778	static void show_screen_async_cb(void* data)
779	{
780	    (void)data;
781	    if (!s_state.initialized || !s_state.running || !s_state.screen) {
782	        return;
783	    }
784	    if (s_state.screen_visible) {
785	        return;
786	    }
787	
788	    /* CJK font selection happens at init() time via the statically-compiled
789	     * lv_font_misans_16_cjk (preferred: 3755 GB2312-1 common chars, baked into
790	     * the binary by lv_font_conv — zero runtime malloc, zero rasterization,
791	     * cannot corrupt the heap).  No runtime TTF loading here.
792	     *
793	     * History: we previously used lv_tiny_ttf_create_data() with a runtime
794	     * MiSans TTF, but stb_truetype's MakeGlyphBitmap write path overran its
795	     * output buffer on certain CJK glyphs and corrupted adjacent NuttX mm heap
796	     * chunk metadata, leading to recursive-assert reboots (mm_foreach /
797	     * nxsched_add_readytorun / nxsem_post_slow in the timer IRQ).  Subsetting
798	     * to 857 KB only delayed the crash; the root cause is the rasterizer, so
799	     * we moved to a pre-rasterized static font.  See lv_font_misans_16_cjk.c
800	     * and the fontgen notes in docs. */
801	    /* Already set in init(); nothing to do at show time. */
802	    syslog(LOG_INFO, "[%s] using static MiSans-16 CJK font\n", TAG);
803	
804	    syslog(LOG_INFO, "[%s] loading chat screen\n", TAG);
805	
806	    /* Save the current screen so we can restore it on stop.
807	     * The launcher (miwear) owns this screen — we must not delete it. */
808	    s_state.prev_screen = lv_screen_active();
809	
810	    lv_screen_load(s_state.screen);
811	    s_state.screen_visible = true;
812	
813	#ifdef LVGL_UI_CARD_SELFTEST
