842	int lvgl_ui_channel_send(const char* text)
843	{
844	    int ret;
845	    async_msg_t* payload;
846	
847	    /* Parameter validation: NULL or empty string */
848	    if (!text || text[0] == '\0') {
849	        syslog(LOG_ERR, "[%s] send: invalid text (NULL or empty)\n", TAG);
850	        return -EINVAL;
851	    }
852	
853	    /* Check channel readiness */
854	    if (!s_state.initialized || !s_state.running) {
855	        syslog(LOG_ERR, "[%s] send: channel not ready (init=%d run=%d)\n",
856	            TAG, s_state.initialized, s_state.running);
857	        return -EINVAL;
858	    }
859	
860	    /* Auto-show chat screen on first Agent reply */
861	    if (!s_state.screen_visible) {
862	        lvgl_ui_channel_show();
863	    }
864	
865	    /* Schedule bubble creation in LVGL thread via lv_async_call.
866	     * This avoids the "Invalidate area is not allowed during rendering"
867	     * assertion crash that occurs when we create LVGL widgets from
868	     * the agent dispatch thread while miwear's LVGL thread is
869	     * mid-render. */
870	    payload = malloc(sizeof(async_msg_t));
871	    if (!payload) {
872	        syslog(LOG_ERR, "[%s] send: async payload alloc failed\n", TAG);
873	        return -ENOMEM;
874	    }
875	
876	    chat_view_copy_text(payload->text, text, LVGL_UI_MSG_MAX_LEN);
877	    payload->is_user = false;
878	
879	    lv_async_call(chat_view_add_message_async_cb, payload);
880	
881	    /* TTS is blocking — run after scheduling the UI update */
882	    ret = voice_channel_speak(text);
883	    if (ret != 0) {
884	        syslog(LOG_ERR, "[%s] voice_channel_speak failed (rc=%d)\n", TAG, ret);
885	    }
886	
887	    return 0;
888	}
