956	/* ── External PTT state (AP→CP RPMsg SET_PTT) ─────────────────── */
957	
958	/* Heap-allocated state for async set_ptt (single int fits in a void* but
959	 * keep a small struct for clarity/future fields). */
960	typedef struct {
961	    int state;
962	} async_ptt_t;
963	
964	static void set_ptt_async_cb(void* data)
965	{
966	    async_ptt_t* p = (async_ptt_t*)data;
967	    if (!p) {
968	        return;
969	    }
970	    if (!s_state.initialized || !s_state.running) {
971	        free(p);
972	        return;
973	    }
974	
975	    switch (p->state) {
976	    case LVGL_UI_PTT_RECORDING:
977	        s_state.is_recording = true;
978	        s_state.is_processing = false;
979	        recording_indicator_start();
980	#ifdef CONFIG_AI_AGENT_PET_STATUS
981	        /* Mirror PTT onto the pet: a recording session reads as "listening". */
982	        pet_status_view_set_state(PET_STATE_LISTENING);
983	#endif
984	        break;
985	    case LVGL_UI_PTT_PROCESSING:
986	        s_state.is_recording = false;
987	        s_state.is_processing = true;
988	        recording_indicator_show_processing();
989	#ifdef CONFIG_AI_AGENT_PET_STATUS
990	        pet_status_view_set_state(PET_STATE_THINKING);
991	#endif
992	        break;
993	    case LVGL_UI_PTT_IDLE:
994	    default:
995	        s_state.is_recording = false;
996	        s_state.is_processing = false;
997	        recording_indicator_stop();
998	#ifdef CONFIG_AI_AGENT_PET_STATUS
999	        pet_status_view_set_state(PET_STATE_IDLE);
1000	#endif
1001	        break;
1002	    }
1003	    free(p);
1004	}
