1006	int lvgl_ui_channel_set_ptt(int state)
1007	{
1008	    async_ptt_t* payload;
1009	
1010	    if (!s_state.initialized || !s_state.running) {
1011	        return -EINVAL;
1012	    }
1013	    /* Coerce unknown values to IDLE. */
1014	    if (state != LVGL_UI_PTT_IDLE && state != LVGL_UI_PTT_RECORDING &&
1015	        state != LVGL_UI_PTT_PROCESSING) {
1016	        state = LVGL_UI_PTT_IDLE;
1017	    }
1018	
1019	    payload = malloc(sizeof(async_ptt_t));
1020	    if (!payload) {
1021	        syslog(LOG_ERR, "[%s] set_ptt: payload alloc failed\n", TAG);
1022	        return -ENOMEM;
1023	    }
1024	    payload->state = state;
1025	    lv_async_call(set_ptt_async_cb, payload);
1026	    return 0;
1027	}
