1129	
1130	    /* Build a lowercase copy (ASCII only; CJK passes through untouched)
1131	     * so substring checks are case-insensitive for the latin keywords. */
1132	    char buf[LVGL_UI_MSG_MAX_LEN];
1133	    size_t i;
1134	    for (i = 0; i < sizeof(buf) - 1 && text[i]; i++) {
1135	        buf[i] = (text[i] >= 'A' && text[i] <= 'Z') ? (text[i] + 32) : text[i];
1136	    }
1137	    buf[i] = '\0';
1138	
1139	    /* Conclusion: explicit yes/no or recommendation phrasing */
1140	    if (strstr(buf, "yes") || strstr(buf, " no") || strstr(buf, "no.") ||
1141	        strstr(buf, "no,") || strstr(buf, "\xe5\x80\xbc\xe5\xbe\x97") /* 值得 */ ||
