1145	    }
1146	
1147	    /* Structured: Gerrit change status keywords (latin) or 状态: */
1148	    if (strstr(buf, "merged") || strstr(buf, "abandoned") ||
1149	        strstr(buf, "status:") || strstr(buf, "\xe7\x8a\xb6\xe6\x80\x81") /* 状态 */ ) {
1150	        return LVGL_UI_CARD_COLOR_STRUCTURED;
1151	    }
