   * qemu goldfish headless skips the first async frame of a screen switched in
   * after lvgl init — the same lazy-flush issue particle_flow_view works around
   * with an explicit invalidate + lv_refr_now.  (Boot-time only; post-boot
   * switches on qemu still won't flush, but real CP /dev/lcd0 is screen-agnostic.) */
  lv_obj_set_style_bg_color(s_pet.screen, lv_color_hex(UI_PAL_BG), 0);
  lv_obj_set_style_bg_opa(s_pet.screen, LV_OPA_COVER, 0);
  lv_obj_invalidate(s_pet.screen);
  lv_refr_now(lv_display_get_default());
  s_pet.visible = true;
  /* Re-assert current state's animation (lv_anim may have been paused off-screen). */
  start_anim_for(s_pet.state);
