 * on the CC0 base face — see gen_pet_expressions.py).  WAITING returns the
 * open-eye base because its blink anim swaps base↔blink itself. */
static const lv_image_dsc_t *sprite_for(enum pet_state st)
{
  switch (st)
    {
      case PET_STATE_LISTENING: return &pet_sprite_eyes_down;
      case PET_STATE_THINKING:  return &pet_sprite_eyes_up;
      case PET_STATE_EXECUTING: return &pet_sprite_focused;
      case PET_STATE_ERROR:     return &pet_sprite_error;
      case PET_STATE_WAITING:
      case PET_STATE_IDLE:
      default:                  return &pet_sprite_base;
    }
}

static void start_anim_for(enum pet_state st)
{
  lv_anim_t a;
  uint32_t color = s_state_color[st];

  stop_anim();
  if (!s_pet.ring || !s_pet.sprite) return;

  /* Ring color always tracks state; base angles reset per effect. */
  lv_obj_set_style_arc_color(s_pet.ring, lv_color_hex(color), 0);

  /* Face tracks state too — each state's expression frame (blink anim swaps it). */
  lv_image_set_src(s_pet.sprite, sprite_for(st));

