1135	/* Classify an Agent reply text into a coarse card category so the
1136	 * left color bar gives a glanceable cue.  Matching is intentionally
1137	 * simple (case-insensitive substring) — this is a visual hint, not
1138	 * a parser.  Returns the palette color for the matched category. */
1139	static uint32_t chat_view_classify_reply(const char* text)
1140	{
1141	    if (!text || !*text) {
1142	        return LVGL_UI_CARD_COLOR_PLAIN;
1143	    }
1144	
1145	    /* Build a lowercase copy (ASCII only; CJK passes through untouched)
1146	     * so substring checks are case-insensitive for the latin keywords. */
1147	    char buf[LVGL_UI_MSG_MAX_LEN];
1148	    size_t i;
1149	    for (i = 0; i < sizeof(buf) - 1 && text[i]; i++) {
1150	        buf[i] = (text[i] >= 'A' && text[i] <= 'Z') ? (text[i] + 32) : text[i];
1151	    }
1152	    buf[i] = '\0';
1153	
1154	    /* Conclusion: explicit yes/no or recommendation phrasing */
1155	    if (strstr(buf, "yes") || strstr(buf, " no") || strstr(buf, "no.") ||
1156	        strstr(buf, "no,") || strstr(buf, "\xe5\x80\xbc\xe5\xbe\x97") /* 值得 */ ||
1157	        strstr(buf, "\xe4\xb8\x8d\xe5\xbb\xba\xe8\xae\xae") /* 不建议 */ ||
1158	        strstr(buf, "\xe5\xbb\xba\xe8\xae\xae") /* 建议 */ ) {
1159	        return LVGL_UI_CARD_COLOR_CONCLUSION;
1160	    }
1161	
1162	    /* Structured: Gerrit change status keywords (latin) or 状态: */
1163	    if (strstr(buf, "merged") || strstr(buf, "abandoned") ||
1164	        strstr(buf, "status:") || strstr(buf, "\xe7\x8a\xb6\xe6\x80\x81") /* 状态 */ ) {
1165	        return LVGL_UI_CARD_COLOR_STRUCTURED;
1166	    }
1167	
1168	    /* Jira: workflow status or assignee fields */
1169	    if (strstr(buf, "more info") || strstr(buf, "assignee") ||
1170	        strstr(buf, "\xe7\xbb\x8f\xe5\x8a\x9e\xe4\xba\xba") /* 经办人 */ ||
1171	        strstr(buf, "jira") ) {
1172	        return LVGL_UI_CARD_COLOR_JIRA;
1173	    }
1174	
1175	    return LVGL_UI_CARD_COLOR_PLAIN;
1176	}
