    }

    /* Auto-dismiss timer */
    s_timer = lv_timer_create(toast_timeout_cb, p->duration_ms, NULL);
    if (s_timer) {
        lv_timer_set_repeat_count(s_timer, 1);
        lv_timer_set_auto_delete(s_timer, true);
    }

    syslog(LOG_INFO, "[%s] toast: %s | %s\n", TAG, p->title, p->body);
